-- Talleres, retiros, horas santas y estaciones (retreats.tipo).
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'levantate-hombre', 'GIBOR-01-LEVANTATE', 'guibor', 'retiro', 1, NULL, 'Levántate y Sé Hombre', NULL, 'El rescate de la masculinidad en un mundo que la tiene confundida.', 'ordinario', NULL, NULL, 'retiro-levantate-hombre.webp', 'publicado', '{\"basadoEn\":null,\"bloques\":[{\"title\":\"El modelo de Cristo\",\"text\":\"Redefinir la hombría mirando al hombre perfecto: lo suficientemente recio para volcar mesas a latigazos, lo suficientemente fuerte para arrodillarse a lavar pies.\"},{\"title\":\"Tomar el timón\",\"text\":\"Un taller sin rodeos sobre asumir la responsabilidad y el liderazgo servicial en la familia, forjar amistades de hierro, dignificar el trabajo y vivir una fe que no se acobarda.\"}],\"temas\":[{\"titulo\":\"Identidad y Masculinidad Verdadera\",\"resumen\":\"Confronta al varón con la máscara que el mundo le impone (fuerza sin heridas, éxito sin vulnerabilidad) y lo invita, a través del rito del espejo roto y el clavo en el madero, a descubrir su verdadero rostro a la luz de Cristo, el \\\"hombre perfecto\\\" capaz de volcar mesas y de arrodillarse a lavar pies.\",\"puntos\":[\"La actividad introductoria busca confrontar al varón con las máscaras que usa para ocultar su vulnerabilidad y sus heridas ante el mundo.\",\"El rito final busca que cada hombre entregue conscientemente sus ataduras e identidad fragmentada, para recibir de Cristo un rostro restaurado y libre de máscaras.\"]},{\"titulo\":\"El Hombre y la Familia\",\"resumen\":\"A partir de la imagen de una silla vacía y una rosa marchita, este tema confronta al varón con la huella —presente o ausente— de su padre terrenal y lo llama a sanar esa herida para asumir con madurez sus tres misiones en el hogar: protector, proveedor y guía espiritual, según el modelo silencioso de San José.\",\"puntos\":[\"La actividad introductoria busca que cada varón reconozca la huella —presente o ausente— de su padre terrenal, y examine qué huella está dejando él mismo en su propia familia.\",\"El rito final busca sellar el compromiso de dejar atrás la ausencia o la dureza de corazón, y regresar al hogar como protector, proveedor y guía espiritual presente.\"]},{\"titulo\":\"Hermandad Masculina\",\"resumen\":\"Este bloque rompe el mito del hombre autosuficiente que \\\"no necesita ayuda\\\", mostrando en las Escrituras —David y Jonatán, Elías y Eliseo, Jesús y Juan, entre otras— que la verdadera hombría se sostiene en la hermandad, y lo sella con un rito de nudos sobre una cuerda común.\",\"puntos\":[\"La actividad introductoria busca que el varón experimente, de forma corporal, que la verdadera fortaleza no está en la autosuficiencia sino en dejarse sostener por sus hermanos.\",\"El rito final busca sellar el compromiso de perdonar a los hermanos de sangre e integrarse a una hermandad espiritual que vele por la santidad mutua.\"]},{\"titulo\":\"El Altar de lo Cotidiano: Trabajo y Responsabilidad\",\"resumen\":\"Contrastando un cofre de monedas doradas con un yunque de trabajo, este tema desenmascara la pereza y la idolatría profesional como dos huidas cobardes de la responsabilidad, y propone el trabajo diario —el taller, la oficina, el campo— como un altar de servicio y co-creación con Dios.\",\"puntos\":[\"La actividad introductoria busca que el varón experimente que todo trabajo digno implica esfuerzo, tal como Dios mismo \\\"se ensució las manos\\\" al formar al hombre.\",\"El rito final busca consagrar el esfuerzo diario como ofrenda a Dios, y no como una fuga cobarde de las responsabilidades familiares.\"]},{\"titulo\":\"El Guerrero Espiritual en el Siglo XXI\",\"resumen\":\"Frente al ruido digital y las mentiras del mundo (\\\"la fe es de cobardes\\\", \\\"sé tu propio dios\\\"), este cierre presenta la oración como el verdadero campo de batalla del hombre contemporáneo y envía a cada varón como guerrero espiritual, custodio de su hogar, su trabajo y su fe.\",\"puntos\":[\"La actividad introductoria busca exponer las mentiras que el mundo repite al varón sobre la fe y la espiritualidad, para que decida arrancarlas de su vida.\",\"El rito final busca consagrar al varón como guerrero espiritual, enviado a custodiar con la oración su hogar, su trabajo y su fe.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"levantate-hombre\",\"codigo\":\"GIBOR-01-LEVANTATE\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":1,\"tema_paso\":null,\"title\":\"Levántate y Sé Hombre\",\"subtitle\":null,\"summary\":\"El rescate de la masculinidad en un mundo que la tiene confundida.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-levantate-hombre.webp\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":null,\"bloques\":[{\"title\":\"El modelo de Cristo\",\"text\":\"Redefinir la hombría mirando al hombre perfecto: lo suficientemente recio para volcar mesas a latigazos, lo suficientemente fuerte para arrodillarse a lavar pies.\"},{\"title\":\"Tomar el timón\",\"text\":\"Un taller sin rodeos sobre asumir la responsabilidad y el liderazgo servicial en la familia, forjar amistades de hierro, dignificar el trabajo y vivir una fe que no se acobarda.\"}],\"temas\":[{\"titulo\":\"Identidad y Masculinidad Verdadera\",\"resumen\":\"Confronta al varón con la máscara que el mundo le impone (fuerza sin heridas, éxito sin vulnerabilidad) y lo invita, a través del rito del espejo roto y el clavo en el madero, a descubrir su verdadero rostro a la luz de Cristo, el \\\"hombre perfecto\\\" capaz de volcar mesas y de arrodillarse a lavar pies.\",\"puntos\":[\"La actividad introductoria busca confrontar al varón con las máscaras que usa para ocultar su vulnerabilidad y sus heridas ante el mundo.\",\"El rito final busca que cada hombre entregue conscientemente sus ataduras e identidad fragmentada, para recibir de Cristo un rostro restaurado y libre de máscaras.\"]},{\"titulo\":\"El Hombre y la Familia\",\"resumen\":\"A partir de la imagen de una silla vacía y una rosa marchita, este tema confronta al varón con la huella —presente o ausente— de su padre terrenal y lo llama a sanar esa herida para asumir con madurez sus tres misiones en el hogar: protector, proveedor y guía espiritual, según el modelo silencioso de San José.\",\"puntos\":[\"La actividad introductoria busca que cada varón reconozca la huella —presente o ausente— de su padre terrenal, y examine qué huella está dejando él mismo en su propia familia.\",\"El rito final busca sellar el compromiso de dejar atrás la ausencia o la dureza de corazón, y regresar al hogar como protector, proveedor y guía espiritual presente.\"]},{\"titulo\":\"Hermandad Masculina\",\"resumen\":\"Este bloque rompe el mito del hombre autosuficiente que \\\"no necesita ayuda\\\", mostrando en las Escrituras —David y Jonatán, Elías y Eliseo, Jesús y Juan, entre otras— que la verdadera hombría se sostiene en la hermandad, y lo sella con un rito de nudos sobre una cuerda común.\",\"puntos\":[\"La actividad introductoria busca que el varón experimente, de forma corporal, que la verdadera fortaleza no está en la autosuficiencia sino en dejarse sostener por sus hermanos.\",\"El rito final busca sellar el compromiso de perdonar a los hermanos de sangre e integrarse a una hermandad espiritual que vele por la santidad mutua.\"]},{\"titulo\":\"El Altar de lo Cotidiano: Trabajo y Responsabilidad\",\"resumen\":\"Contrastando un cofre de monedas doradas con un yunque de trabajo, este tema desenmascara la pereza y la idolatría profesional como dos huidas cobardes de la responsabilidad, y propone el trabajo diario —el taller, la oficina, el campo— como un altar de servicio y co-creación con Dios.\",\"puntos\":[\"La actividad introductoria busca que el varón experimente que todo trabajo digno implica esfuerzo, tal como Dios mismo \\\"se ensució las manos\\\" al formar al hombre.\",\"El rito final busca consagrar el esfuerzo diario como ofrenda a Dios, y no como una fuga cobarde de las responsabilidades familiares.\"]},{\"titulo\":\"El Guerrero Espiritual en el Siglo XXI\",\"resumen\":\"Frente al ruido digital y las mentiras del mundo (\\\"la fe es de cobardes\\\", \\\"sé tu propio dios\\\"), este cierre presenta la oración como el verdadero campo de batalla del hombre contemporáneo y envía a cada varón como guerrero espiritual, custodio de su hogar, su trabajo y su fe.\",\"puntos\":[\"La actividad introductoria busca exponer las mentiras que el mundo repite al varón sobre la fe y la espiritualidad, para que decida arrancarlas de su vida.\",\"El rito final busca consagrar al varón como guerrero espiritual, enviado a custodiar con la oración su hogar, su trabajo y su fe.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'levantate-hombre');
