  SELECT 'sanson', 'GIBOR-02-SANSON', 'guibor', 'retiro', 2, 'Identidad y masculinidad', 'Sansón', NULL, 'La fuerza no es el músculo: es saber a quién perteneces.', 'ordinario', NULL, NULL, 'retiro-sanson.jpg', 'proximamente', '{\"basadoEn\":\"Sansón, juez de Israel\",\"bloques\":[{\"title\":\"El secreto no está en el pelo\",\"text\":\"Sansón tenía la fuerza de un ejército y la disciplina de un niño. Este retiro confronta el mito de que la masculinidad se mide en bíceps, cuando en realidad se mide en dominio propio.\"},{\"title\":\"Dalila tiene muchos nombres\",\"text\":\"Todo hombre tiene su \\\"Dalila\\\": la debilidad que sabe exactamente dónde presionar. Identificar qué te desgasta la fuerza en silencio, antes de que te corte el cabello.\"},{\"title\":\"De las ruinas al templo\",\"text\":\"Aun después de perderlo todo, Dios usó la última fuerza de Sansón para un propósito mayor. Ninguna caída es definitiva si vuelves a apoyarte en las columnas correctas.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"sanson\",\"codigo\":\"GIBOR-02-SANSON\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":2,\"tema_paso\":\"Identidad y masculinidad\",\"title\":\"Sansón\",\"subtitle\":null,\"summary\":\"La fuerza no es el músculo: es saber a quién perteneces.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-sanson.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Sansón, juez de Israel\",\"bloques\":[{\"title\":\"El secreto no está en el pelo\",\"text\":\"Sansón tenía la fuerza de un ejército y la disciplina de un niño. Este retiro confronta el mito de que la masculinidad se mide en bíceps, cuando en realidad se mide en dominio propio.\"},{\"title\":\"Dalila tiene muchos nombres\",\"text\":\"Todo hombre tiene su \\\"Dalila\\\": la debilidad que sabe exactamente dónde presionar. Identificar qué te desgasta la fuerza en silencio, antes de que te corte el cabello.\"},{\"title\":\"De las ruinas al templo\",\"text\":\"Aun después de perderlo todo, Dios usó la última fuerza de Sansón para un propósito mayor. Ninguna caída es definitiva si vuelves a apoyarte en las columnas correctas.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
