  SELECT 'tobias', 'GIBOR-03-TOBIAS', 'guibor', 'retiro', 3, 'Familia', 'Tobías', NULL, 'La familia no se hereda perfecta, se construye con fe en el camino.', 'ordinario', NULL, NULL, 'retiro-tobias.jpg', 'proximamente', '{\"basadoEn\":\"el libro de Tobías\",\"bloques\":[{\"title\":\"Un padre que confía a ciegas\",\"text\":\"Tobit envía a su hijo a un viaje incierto confiando en un ángel disfrazado. Hablar de la fe que un padre transmite sin necesidad de controlarlo todo.\"},{\"title\":\"El ángel que camina contigo\",\"text\":\"Rafael acompaña a Tobías paso a paso: la certeza de que Dios manda compañía para las decisiones familiares grandes, como el matrimonio, el sustento o la sanación.\"},{\"title\":\"Sara, Ragüel y el matrimonio con propósito\",\"text\":\"El matrimonio de Tobías y Sara nace de oración, no de impulso. Construir un hogar con esa misma intención, desde el primer paso.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"tobias\",\"codigo\":\"GIBOR-03-TOBIAS\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":3,\"tema_paso\":\"Familia\",\"title\":\"Tobías\",\"subtitle\":null,\"summary\":\"La familia no se hereda perfecta, se construye con fe en el camino.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-tobias.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el libro de Tobías\",\"bloques\":[{\"title\":\"Un padre que confía a ciegas\",\"text\":\"Tobit envía a su hijo a un viaje incierto confiando en un ángel disfrazado. Hablar de la fe que un padre transmite sin necesidad de controlarlo todo.\"},{\"title\":\"El ángel que camina contigo\",\"text\":\"Rafael acompaña a Tobías paso a paso: la certeza de que Dios manda compañía para las decisiones familiares grandes, como el matrimonio, el sustento o la sanación.\"},{\"title\":\"Sara, Ragüel y el matrimonio con propósito\",\"text\":\"El matrimonio de Tobías y Sara nace de oración, no de impulso. Construir un hogar con esa misma intención, desde el primer paso.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'tobias');
