  SELECT 'jonatan', 'GIBOR-04-JONATAN', 'guibor', 'retiro', 4, 'Amistad y Hermandad', 'Jonatán', NULL, 'La amistad real se mide en lo que estás dispuesto a perder por el otro.', 'ordinario', NULL, NULL, 'retiro-jonatan.jpg', 'proximamente', '{\"basadoEn\":\"Jonatán, hijo de Saúl\",\"bloques\":[{\"title\":\"Un pacto sin envidia\",\"text\":\"Jonatán, heredero al trono, ama a David sabiendo que Dios lo eligió a él en su lugar. Hablar de la hermandad que no compite.\"},{\"title\":\"Amistad de riesgo\",\"text\":\"Jonatán arriesga la relación con su padre y su propia seguridad para proteger a David: la amistad que cuesta algo real, no la que solo es cómoda.\"},{\"title\":\"El pacto que sobrevive a la muerte\",\"text\":\"Jonatán pide a David que cuide a su familia después de morir. Construir amistades que trascienden la conveniencia del momento.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"jonatan\",\"codigo\":\"GIBOR-04-JONATAN\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":4,\"tema_paso\":\"Amistad y Hermandad\",\"title\":\"Jonatán\",\"subtitle\":null,\"summary\":\"La amistad real se mide en lo que estás dispuesto a perder por el otro.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-jonatan.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Jonatán, hijo de Saúl\",\"bloques\":[{\"title\":\"Un pacto sin envidia\",\"text\":\"Jonatán, heredero al trono, ama a David sabiendo que Dios lo eligió a él en su lugar. Hablar de la hermandad que no compite.\"},{\"title\":\"Amistad de riesgo\",\"text\":\"Jonatán arriesga la relación con su padre y su propia seguridad para proteger a David: la amistad que cuesta algo real, no la que solo es cómoda.\"},{\"title\":\"El pacto que sobrevive a la muerte\",\"text\":\"Jonatán pide a David que cuide a su familia después de morir. Construir amistades que trascienden la conveniencia del momento.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'jonatan');
