  SELECT 'jose-nazaret', 'GIBOR-05-JOSENAZARET', 'guibor', 'retiro', 5, 'Trabajo y Responsabilidad', 'José de Nazaret', NULL, 'La verdadera hombría se demuestra en el silencio de quien sostiene sin pedir reconocimiento.', 'ordinario', '[\"adviento\"]', NULL, 'retiro-jose-nazaret.jpg', 'proximamente', '{\"basadoEn\":\"San José, esposo de María\",\"bloques\":[{\"title\":\"El justo que no huye\",\"text\":\"José descubre un embarazo que no comprende y, en vez de huir, se queda a proteger. Hablar de la responsabilidad que no depende de tener todas las respuestas.\"},{\"title\":\"El taller como altar\",\"text\":\"Su trabajo de carpintero educó al mismo Hijo de Dios. Dignificar el trabajo ordinario como lugar de santidad y provisión.\"},{\"title\":\"Proteger sin protagonismo\",\"text\":\"José nunca habla en el Evangelio, pero cada decisión suya cambia la historia. Ser el hombre que sostiene la casa sin necesitar el centro del escenario.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"jose-nazaret\",\"codigo\":\"GIBOR-05-JOSENAZARET\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":5,\"tema_paso\":\"Trabajo y Responsabilidad\",\"title\":\"José de Nazaret\",\"subtitle\":null,\"summary\":\"La verdadera hombría se demuestra en el silencio de quien sostiene sin pedir reconocimiento.\",\"season_slug\":\"ordinario\",\"season_secondary\":[\"adviento\"],\"corte_simja\":null,\"cover\":\"retiro-jose-nazaret.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"San José, esposo de María\",\"bloques\":[{\"title\":\"El justo que no huye\",\"text\":\"José descubre un embarazo que no comprende y, en vez de huir, se queda a proteger. Hablar de la responsabilidad que no depende de tener todas las respuestas.\"},{\"title\":\"El taller como altar\",\"text\":\"Su trabajo de carpintero educó al mismo Hijo de Dios. Dignificar el trabajo ordinario como lugar de santidad y provisión.\"},{\"title\":\"Proteger sin protagonismo\",\"text\":\"José nunca habla en el Evangelio, pero cada decisión suya cambia la historia. Ser el hombre que sostiene la casa sin necesitar el centro del escenario.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'jose-nazaret');
