  SELECT 'josue', 'GIBOR-06-JOSUE', 'guibor', 'retiro', 6, 'Hombre espiritual Siglo XXI', 'Josué', NULL, 'Heredar la promesa no es suerte: es esfuerzo, valentía y obediencia sin atajos.', 'ordinario', NULL, NULL, 'retiro-josue.jpg', 'proximamente', '{\"basadoEn\":\"el libro de Josué\",\"bloques\":[{\"title\":\"De asistente a líder\",\"text\":\"Josué pasa 40 años como segundo de Moisés antes de cruzar el Jordán. Hablar del tiempo de formación silenciosa antes del liderazgo.\"},{\"title\":\"\\\"Esfuérzate y sé valiente\\\"\",\"text\":\"La orden que Dios repite tres veces al inicio del libro. La valentía como mandato, no como sentimiento opcional.\"},{\"title\":\"Escoger a quién servir hoy\",\"text\":\"\\\"Escojan hoy a quién han de servir\\\": el hombre espiritual del siglo XXI decide su fe activamente, no por herencia cultural.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"josue\",\"codigo\":\"GIBOR-06-JOSUE\",\"derej_slug\":\"guibor\",\"tipo\":\"retiro\",\"paso\":6,\"tema_paso\":\"Hombre espiritual Siglo XXI\",\"title\":\"Josué\",\"subtitle\":null,\"summary\":\"Heredar la promesa no es suerte: es esfuerzo, valentía y obediencia sin atajos.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-josue.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el libro de Josué\",\"bloques\":[{\"title\":\"De asistente a líder\",\"text\":\"Josué pasa 40 años como segundo de Moisés antes de cruzar el Jordán. Hablar del tiempo de formación silenciosa antes del liderazgo.\"},{\"title\":\"\\\"Esfuérzate y sé valiente\\\"\",\"text\":\"La orden que Dios repite tres veces al inicio del libro. La valentía como mandato, no como sentimiento opcional.\"},{\"title\":\"Escoger a quién servir hoy\",\"text\":\"\\\"Escojan hoy a quién han de servir\\\": el hombre espiritual del siglo XXI decide su fe activamente, no por herencia cultural.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'josue');
