  SELECT 'fuiste-mujer', 'KAVOD-01-FUISTEMUJER', 'kavod', 'retiro', 1, NULL, 'Fuiste Hecha Mujer', NULL, 'El genio femenino como obra maestra y pilar de la creación.', 'ordinario', NULL, NULL, 'retiro-fuiste-mujer.webp', 'proximamente', '{\"basadoEn\":\"más de 7 mujeres de la Biblia\",\"bloques\":[{\"title\":\"Más que un complemento\",\"text\":\"Repasar la historia de las mujeres clave en la Biblia para derribar el mito de que la mujer es un \\\"plan B\\\". Eres la pieza integral que le da sentido a la vida misma.\"},{\"title\":\"Fuerza y resiliencia divina\",\"text\":\"Notar cómo Dios ha usado la intuición, la fortaleza y la capacidad de amar de la mujer para cambiar el rumbo de la historia de la salvación, y cómo espera hacer lo mismo contigo hoy.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"fuiste-mujer\",\"codigo\":\"KAVOD-01-FUISTEMUJER\",\"derej_slug\":\"kavod\",\"tipo\":\"retiro\",\"paso\":1,\"tema_paso\":null,\"title\":\"Fuiste Hecha Mujer\",\"subtitle\":null,\"summary\":\"El genio femenino como obra maestra y pilar de la creación.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-fuiste-mujer.webp\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"más de 7 mujeres de la Biblia\",\"bloques\":[{\"title\":\"Más que un complemento\",\"text\":\"Repasar la historia de las mujeres clave en la Biblia para derribar el mito de que la mujer es un \\\"plan B\\\". Eres la pieza integral que le da sentido a la vida misma.\"},{\"title\":\"Fuerza y resiliencia divina\",\"text\":\"Notar cómo Dios ha usado la intuición, la fortaleza y la capacidad de amar de la mujer para cambiar el rumbo de la historia de la salvación, y cómo espera hacer lo mismo contigo hoy.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'fuiste-mujer');
