  SELECT 'eva', 'KAVOD-02-EVA', 'kavod', 'retiro', 2, 'Identidad y dignidad', 'Eva', NULL, 'Antes de la caída, hubo una obra maestra: entender tu dignidad original.', 'ordinario', '[\"cuaresma\"]', NULL, 'retiro-eva.jpg', 'proximamente', '{\"basadoEn\":\"Eva, la primera mujer\",\"bloques\":[{\"title\":\"Formada, no improvisada\",\"text\":\"Eva no es un accesorio de Adán; es la culminación de la creación. Recuperar la dignidad que antecede a cualquier herida o mentira recibida.\"},{\"title\":\"La mentira más antigua\",\"text\":\"La serpiente no ataca el cuerpo, ataca la identidad: \\\"¿de verdad dijo Dios...?\\\". Reconocer cómo esa misma mentira sigue operando hoy.\"},{\"title\":\"De la vergüenza a la promesa\",\"text\":\"Aun en la caída, Dios no abandona: promete descendencia que aplastará al mal. Tu historia con heridas no es el final de tu identidad.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"eva\",\"codigo\":\"KAVOD-02-EVA\",\"derej_slug\":\"kavod\",\"tipo\":\"retiro\",\"paso\":2,\"tema_paso\":\"Identidad y dignidad\",\"title\":\"Eva\",\"subtitle\":null,\"summary\":\"Antes de la caída, hubo una obra maestra: entender tu dignidad original.\",\"season_slug\":\"ordinario\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"retiro-eva.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Eva, la primera mujer\",\"bloques\":[{\"title\":\"Formada, no improvisada\",\"text\":\"Eva no es un accesorio de Adán; es la culminación de la creación. Recuperar la dignidad que antecede a cualquier herida o mentira recibida.\"},{\"title\":\"La mentira más antigua\",\"text\":\"La serpiente no ataca el cuerpo, ataca la identidad: \\\"¿de verdad dijo Dios...?\\\". Reconocer cómo esa misma mentira sigue operando hoy.\"},{\"title\":\"De la vergüenza a la promesa\",\"text\":\"Aun en la caída, Dios no abandona: promete descendencia que aplastará al mal. Tu historia con heridas no es el final de tu identidad.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'eva');
