  SELECT 'betania', 'KAVOD-05-BETANIA', 'kavod', 'retiro', 5, 'Trabajo y vocación', 'Betania', NULL, 'Servir con las manos y creer con el corazón no son caminos distintos.', 'ordinario', '[\"cuaresma\"]', NULL, 'retiro-betania.jpg', 'proximamente', '{\"basadoEn\":\"Marta y María, hermanas de Lázaro\",\"bloques\":[{\"title\":\"La que se mueve por amor\",\"text\":\"Marta no es \\\"la que no entendió\\\"; es la que abre su casa, organiza y sirve. Dignificar el trabajo, la logística y el servicio como vocación, no como distracción.\"},{\"title\":\"\\\"Sí creo\\\" antes del milagro\",\"text\":\"En la resurrección de Lázaro es Marta quien hace la confesión de fe más clara del Evangelio: \\\"Yo creo que tú eres el Cristo\\\". El trabajo no compite con la fe: la sostiene.\"},{\"title\":\"Ordenar la casa sin perder el centro\",\"text\":\"Aprender de su corrección en Lucas 10 sin borrar su fortaleza en Juan 11: el equilibrio entre hacer y estar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"betania\",\"codigo\":\"KAVOD-05-BETANIA\",\"derej_slug\":\"kavod\",\"tipo\":\"retiro\",\"paso\":5,\"tema_paso\":\"Trabajo y vocación\",\"title\":\"Betania\",\"subtitle\":null,\"summary\":\"Servir con las manos y creer con el corazón no son caminos distintos.\",\"season_slug\":\"ordinario\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"retiro-betania.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Marta y María, hermanas de Lázaro\",\"bloques\":[{\"title\":\"La que se mueve por amor\",\"text\":\"Marta no es \\\"la que no entendió\\\"; es la que abre su casa, organiza y sirve. Dignificar el trabajo, la logística y el servicio como vocación, no como distracción.\"},{\"title\":\"\\\"Sí creo\\\" antes del milagro\",\"text\":\"En la resurrección de Lázaro es Marta quien hace la confesión de fe más clara del Evangelio: \\\"Yo creo que tú eres el Cristo\\\". El trabajo no compite con la fe: la sostiene.\"},{\"title\":\"Ordenar la casa sin perder el centro\",\"text\":\"Aprender de su corrección en Lucas 10 sin borrar su fortaleza en Juan 11: el equilibrio entre hacer y estar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
