  SELECT 'shema', 'MESHARET-SHEMABAR', 'mesharet', 'retiro', NULL, NULL, 'Shemá Bar · Adoración en movimiento', NULL, 'La adoración no es un pasatiempo dominical; es una posición de combate.', 'ordinario', NULL, NULL, 'retiro-shema.webp', 'proximamente', '{\"basadoEn\":\"David, Asaf, Hemán y Jedutún, Miriam hermana de Moisés, los hijos de Coré y los levitas\",\"bloques\":[{\"title\":\"El ADN del levita\",\"text\":\"Basado en los grandes adoradores (David, Asaf, Hemán, Jedutún), entenderemos que el talento musical, vocal y dancístico no es para lucirse, es munición pesada y ofrenda directa al cielo.\"},{\"title\":\"Teología en la práctica\",\"text\":\"Aterrizaremos las encíclicas Musicae Sacrae y Sacrosanctum Concilium para que dejen de ser documentos empolvados y se conviertan en la partitura de nuestro ministerio.\"},{\"title\":\"El peso del coro\",\"text\":\"Si el coro no ora, solo hace ruido. Comprenderemos la función ministerial real: llevar a una asamblea entera a la presencia de Dios.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"David\",\"Asaf\",\"Hemán\",\"Jedutún\",\"Miriam, hermana de Moisés\",\"Los hijos de Coré\",\"Levitas\"],\"chipsLabel\":\"Figuras bíblicas\"}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"shema\",\"codigo\":\"MESHARET-SHEMABAR\",\"derej_slug\":\"mesharet\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Shemá Bar · Adoración en movimiento\",\"subtitle\":null,\"summary\":\"La adoración no es un pasatiempo dominical; es una posición de combate.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-shema.webp\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"David, Asaf, Hemán y Jedutún, Miriam hermana de Moisés, los hijos de Coré y los levitas\",\"bloques\":[{\"title\":\"El ADN del levita\",\"text\":\"Basado en los grandes adoradores (David, Asaf, Hemán, Jedutún), entenderemos que el talento musical, vocal y dancístico no es para lucirse, es munición pesada y ofrenda directa al cielo.\"},{\"title\":\"Teología en la práctica\",\"text\":\"Aterrizaremos las encíclicas Musicae Sacrae y Sacrosanctum Concilium para que dejen de ser documentos empolvados y se conviertan en la partitura de nuestro ministerio.\"},{\"title\":\"El peso del coro\",\"text\":\"Si el coro no ora, solo hace ruido. Comprenderemos la función ministerial real: llevar a una asamblea entera a la presencia de Dios.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"David\",\"Asaf\",\"Hemán\",\"Jedutún\",\"Miriam, hermana de Moisés\",\"Los hijos de Coré\",\"Levitas\"],\"chipsLabel\":\"Figuras bíblicas\"}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'shema');
