  SELECT 'emmanuel', 'JAIM-EMMANUEL', 'jaim', 'retiro', NULL, NULL, 'Emmanuel', NULL, 'La promesa más antigua de la humanidad estaba a punto de cumplirse: Dios mismo vendría a rescatarnos.', 'adviento', NULL, NULL, 'retiro-emmanuel.jpg', 'publicado', '{\"basadoEn\":\"las profecías mesiánicas del Antiguo Testamento\",\"bloques\":[{\"title\":\"La promesa en medio de la ruina\",\"text\":\"Desde el Génesis, Dios promete un descendiente que aplastará el mal. Recorrer cómo esa promesa se sostiene generación tras generación aun en medio del fracaso humano.\"},{\"title\":\"La profecía que se atrevió a nombrar el lugar\",\"text\":\"Isaías y Miqueas anuncian con siglos de anticipación el nombre, el linaje y hasta el pueblo del Mesías. Dios no improvisa: cumple lo que promete, en sus tiempos.\"},{\"title\":\"\\\"Dios con nosotros\\\"\",\"text\":\"Emmanuel no es solo un nombre, es una dirección: Dios ya no observa desde lejos, decide habitar contigo. Vivir el Adviento como la espera activa de esa cercanía.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"emmanuel\",\"codigo\":\"JAIM-EMMANUEL\",\"derej_slug\":\"jaim\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Emmanuel\",\"subtitle\":null,\"summary\":\"La promesa más antigua de la humanidad estaba a punto de cumplirse: Dios mismo vendría a rescatarnos.\",\"season_slug\":\"adviento\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-emmanuel.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"las profecías mesiánicas del Antiguo Testamento\",\"bloques\":[{\"title\":\"La promesa en medio de la ruina\",\"text\":\"Desde el Génesis, Dios promete un descendiente que aplastará el mal. Recorrer cómo esa promesa se sostiene generación tras generación aun en medio del fracaso humano.\"},{\"title\":\"La profecía que se atrevió a nombrar el lugar\",\"text\":\"Isaías y Miqueas anuncian con siglos de anticipación el nombre, el linaje y hasta el pueblo del Mesías. Dios no improvisa: cumple lo que promete, en sus tiempos.\"},{\"title\":\"\\\"Dios con nosotros\\\"\",\"text\":\"Emmanuel no es solo un nombre, es una dirección: Dios ya no observa desde lejos, decide habitar contigo. Vivir el Adviento como la espera activa de esa cercanía.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'emmanuel');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'dos-hermanos', 'JAIM-DOSHERMANOS', 'jaim', 'retiro', NULL, NULL, 'Dos Hermanos', NULL, 'Dos hermanos, el mismo origen, el mismo llamado: lo que cambia el destino es la decisión, no la sangre.', 'ordinario', '[\"cuaresma\"]', NULL, 'retiro-dos-hermanos.jpg', 'proximamente', '{\"basadoEn\":\"la dualidad de las decisiones, la voluntad y las acciones en distintos pares de hermanos de la Escritura\",\"bloques\":[{\"title\":\"Caín y Abel: la ofrenda que delata el corazón\",\"text\":\"Ambos ofrecen algo a Dios, pero solo uno ofrece con el corazón entero. Confrontar la diferencia entre cumplir un rito y entregar de verdad lo mejor que tienes.\"},{\"title\":\"José y Benjamín: crecer más allá de ser \\\"el favorito\\\"\",\"text\":\"Los dos hijos amados de Jacob no se definen por el cariño que reciben, sino por la fidelidad que construyen cuando nadie los está mirando ni favoreciendo.\"},{\"title\":\"El Hijo Pródigo y el Hijo Mayor: dos formas de estar lejos del Padre\",\"text\":\"Uno se pierde en el pecado evidente; el otro se pierde en la obediencia amargada que nunca entra a la fiesta. Ambos necesitan la misma gracia.\"},{\"title\":\"Esaú y Jacob: lo que vale una bendición\",\"text\":\"Uno vende su primogenitura por un plato de comida; el otro la obtiene con engaño. Ninguno gana limpio: aprender que atajos y desprecios tienen consecuencias que duran generaciones.\"},{\"title\":\"Los hijos de la parábola (Mt 21): entre el decir y el hacer\",\"text\":\"Uno dice que sí y no va a la viña; el otro dice que no y termina yendo. Jesús mide la obediencia real, no la respuesta que suena bien.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"Caín y Abel\",\"José y Benjamín\",\"Hijo Pródigo e Hijo Mayor\",\"Esaú y Jacob\",\"Los hijos de la parábola (Mt 21)\"],\"chipsLabel\":\"Parejas de hermanos\"}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"dos-hermanos\",\"codigo\":\"JAIM-DOSHERMANOS\",\"derej_slug\":\"jaim\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Dos Hermanos\",\"subtitle\":null,\"summary\":\"Dos hermanos, el mismo origen, el mismo llamado: lo que cambia el destino es la decisión, no la sangre.\",\"season_slug\":\"ordinario\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"retiro-dos-hermanos.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la dualidad de las decisiones, la voluntad y las acciones en distintos pares de hermanos de la Escritura\",\"bloques\":[{\"title\":\"Caín y Abel: la ofrenda que delata el corazón\",\"text\":\"Ambos ofrecen algo a Dios, pero solo uno ofrece con el corazón entero. Confrontar la diferencia entre cumplir un rito y entregar de verdad lo mejor que tienes.\"},{\"title\":\"José y Benjamín: crecer más allá de ser \\\"el favorito\\\"\",\"text\":\"Los dos hijos amados de Jacob no se definen por el cariño que reciben, sino por la fidelidad que construyen cuando nadie los está mirando ni favoreciendo.\"},{\"title\":\"El Hijo Pródigo y el Hijo Mayor: dos formas de estar lejos del Padre\",\"text\":\"Uno se pierde en el pecado evidente; el otro se pierde en la obediencia amargada que nunca entra a la fiesta. Ambos necesitan la misma gracia.\"},{\"title\":\"Esaú y Jacob: lo que vale una bendición\",\"text\":\"Uno vende su primogenitura por un plato de comida; el otro la obtiene con engaño. Ninguno gana limpio: aprender que atajos y desprecios tienen consecuencias que duran generaciones.\"},{\"title\":\"Los hijos de la parábola (Mt 21): entre el decir y el hacer\",\"text\":\"Uno dice que sí y no va a la viña; el otro dice que no y termina yendo. Jesús mide la obediencia real, no la respuesta que suena bien.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"Caín y Abel\",\"José y Benjamín\",\"Hijo Pródigo e Hijo Mayor\",\"Esaú y Jacob\",\"Los hijos de la parábola (Mt 21)\"],\"chipsLabel\":\"Parejas de hermanos\"}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'dos-hermanos');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'barrabas', 'JAIM-BARRABAS', 'jaim', 'retiro', NULL, NULL, 'Barrabás', NULL, 'Preferimos casi cualquier cosa antes que a Jesús; y aun así, Él sigue dispuesto a tomar nuestro lugar.', 'cuaresma', NULL, NULL, 'retiro-barrabas.jpg', 'proximamente', '{\"basadoEn\":\"Barrabás, el ladrón y asesino que el pueblo decidió liberar en lugar de Jesús\",\"bloques\":[{\"title\":\"El sentido de la Cuaresma\",\"text\":\"Este relato es la síntesis cruda de la Cuaresma: un inocente condenado, un culpable liberado. Entender los 40 días como el tiempo para mirar de frente ese intercambio.\"},{\"title\":\"Salvado por el que toma tu condena\",\"text\":\"Jesús no es solo ejemplo, es sustituto: carga la sentencia que era nuestra para que la libertad de Barrabás pudiera ser también la nuestra.\"},{\"title\":\"\\\"Suéltanos a Barrabás\\\"\",\"text\":\"La multitud tenía a la Justicia frente a sus ojos y prefirió al criminal. Reconocer cuántas veces seguimos eligiendo cualquier cosa antes que a Cristo.\"},{\"title\":\"Cuando señalamos con el dedo\",\"text\":\"No hicieron falta clavos para condenarlo: bastaron gritos, indiferencia y actitudes cotidianas. Examinar cómo seguimos gritando \\\"¡crucifícalo!\\\" sin darnos cuenta, con gestos de todos los días.\"},{\"title\":\"Los mismos ojos de amor\",\"text\":\"Ni en el momento de ser cambiado por un asesino, Jesús deja de mirar con amor. Esa mirada sigue dispuesta a dar la vida por ti, hoy mismo.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"barrabas\",\"codigo\":\"JAIM-BARRABAS\",\"derej_slug\":\"jaim\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Barrabás\",\"subtitle\":null,\"summary\":\"Preferimos casi cualquier cosa antes que a Jesús; y aun así, Él sigue dispuesto a tomar nuestro lugar.\",\"season_slug\":\"cuaresma\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-barrabas.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Barrabás, el ladrón y asesino que el pueblo decidió liberar en lugar de Jesús\",\"bloques\":[{\"title\":\"El sentido de la Cuaresma\",\"text\":\"Este relato es la síntesis cruda de la Cuaresma: un inocente condenado, un culpable liberado. Entender los 40 días como el tiempo para mirar de frente ese intercambio.\"},{\"title\":\"Salvado por el que toma tu condena\",\"text\":\"Jesús no es solo ejemplo, es sustituto: carga la sentencia que era nuestra para que la libertad de Barrabás pudiera ser también la nuestra.\"},{\"title\":\"\\\"Suéltanos a Barrabás\\\"\",\"text\":\"La multitud tenía a la Justicia frente a sus ojos y prefirió al criminal. Reconocer cuántas veces seguimos eligiendo cualquier cosa antes que a Cristo.\"},{\"title\":\"Cuando señalamos con el dedo\",\"text\":\"No hicieron falta clavos para condenarlo: bastaron gritos, indiferencia y actitudes cotidianas. Examinar cómo seguimos gritando \\\"¡crucifícalo!\\\" sin darnos cuenta, con gestos de todos los días.\"},{\"title\":\"Los mismos ojos de amor\",\"text\":\"Ni en el momento de ser cambiado por un asesino, Jesús deja de mirar con amor. Esa mirada sigue dispuesta a dar la vida por ti, hoy mismo.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'barrabas');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'golgota', 'JAIM-GOLGOTA', 'jaim', 'taller', NULL, NULL, 'Gólgota', NULL, 'La redención del fracaso humano a través de un amor brutal e ineludible.', 'cuaresma', '[\"pascua\"]', NULL, 'retiro-golgota.webp', 'proximamente', '{\"basadoEn\":\"la Pasión, Muerte y Resurrección de Cristo\",\"bloques\":[{\"title\":\"El giro de trama (Felix Culpa)\",\"text\":\"Sí, Eva por andar de \\\"inventada\\\" nos costó el Edén, pero provocó la mayor historia de rescate: nos trajo a Cristo. El Gólgota no es solo un dato histórico, es la tumba de Adán (la vieja naturaleza) y la cuna del hombre nuevo.\"},{\"title\":\"Tú eres un Gólgota\",\"text\":\"Todos tenemos una zona de desastre, áreas de pecado y fracaso. El retiro te lleva a entender que exactamente ahí, donde huele a muerte, es donde Dios planta la cruz para que brote la vida.\"},{\"title\":\"La anatomía del sacrificio\",\"text\":\"No es un amor romántico de película; es el poema crudo de Isaías 53. Es entender el dolor de la separación que causa nuestro pecado y mirar de frente el precio que Dios pagó para reconciliarnos. No hay gracia barata.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"golgota\",\"codigo\":\"JAIM-GOLGOTA\",\"derej_slug\":\"jaim\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Gólgota\",\"subtitle\":null,\"summary\":\"La redención del fracaso humano a través de un amor brutal e ineludible.\",\"season_slug\":\"cuaresma\",\"season_secondary\":[\"pascua\"],\"corte_simja\":null,\"cover\":\"retiro-golgota.webp\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la Pasión, Muerte y Resurrección de Cristo\",\"bloques\":[{\"title\":\"El giro de trama (Felix Culpa)\",\"text\":\"Sí, Eva por andar de \\\"inventada\\\" nos costó el Edén, pero provocó la mayor historia de rescate: nos trajo a Cristo. El Gólgota no es solo un dato histórico, es la tumba de Adán (la vieja naturaleza) y la cuna del hombre nuevo.\"},{\"title\":\"Tú eres un Gólgota\",\"text\":\"Todos tenemos una zona de desastre, áreas de pecado y fracaso. El retiro te lleva a entender que exactamente ahí, donde huele a muerte, es donde Dios planta la cruz para que brote la vida.\"},{\"title\":\"La anatomía del sacrificio\",\"text\":\"No es un amor romántico de película; es el poema crudo de Isaías 53. Es entender el dolor de la separación que causa nuestro pecado y mirar de frente el precio que Dios pagó para reconciliarnos. No hay gracia barata.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'golgota');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'alabastro-roto', 'JAIM-ALABASTROROTO', 'jaim', 'retiro', NULL, NULL, 'Alabastro Roto', NULL, 'Quebrar lo más valioso que tienes, sin calcularlo, es la forma más alta de decirle a Cristo que lo vale todo.', 'cuaresma', NULL, NULL, 'JAIM-ALABASTROROTO.jpg', 'proximamente', '{\"basadoEn\":\"la mujer que unge a Jesús con perfume de nardo puro en Betania\",\"bloques\":[{\"title\":\"Romper el frasco, no solo abrirlo\",\"text\":\"A diferencia de perfumar poco a poco, la mujer de Betania rompe de un solo golpe el cuello del alabastro: no hay marcha atrás ni cálculo posible. Un retiro sobre la entrega total, no la entrega medida.\"},{\"title\":\"Pieza intensa, con confesión disponible\",\"text\":\"Por la profundidad emocional y espiritual del contenido —quiebre, vergüenza, entrega radical—, este retiro contempla un sacerdote disponible para confesión durante todo el evento, no solo al cierre.\"}],\"temas\":[{\"titulo\":\"Preparar el Alabastro\",\"resumen\":\"A partir del valor del perfume de nardo puro —cerca de un año de salario—, este tema invita a cada participante a nombrar su propio \\\"alabastro\\\": lo que más le cuesta soltar (tiempo, orgullo, control, una relación, una imagen).\",\"puntos\":[\"La actividad introductoria busca que cada participante identifique con honestidad qué es lo más valioso —no necesariamente material— que aún no ha puesto en manos de Cristo.\",\"El tema busca desmontar la idea de que entregarse a Dios empieza por dar lo que sobra: empieza por reconocer lo que de verdad cuesta.\"]},{\"titulo\":\"El Quiebre\",\"resumen\":\"Este tema contempla el gesto de romper el frasco frente a todos, sin pedir permiso ni justificarse, para mostrar que la entrega total no se negocia ni se explica ante la mirada ajena.\",\"puntos\":[\"La dinámica busca que los participantes experimenten, de forma simbólica, lo incómodo de un gesto de amor que a otros les puede parecer excesivo o vergonzoso.\",\"El tema busca liberar a cada uno del miedo al \\\"qué dirán\\\" cuando se trata de amar a Cristo sin medida.\"]},{\"titulo\":\"El Reproche y el Silencio de Ella\",\"resumen\":\"Frente a quienes la critican por \\\"desperdiciar\\\" el perfume, la mujer no se defiende ni se justifica — y es Jesús quien responde por ella: \\\"Ella hizo lo que pudo.\\\"\",\"puntos\":[\"La actividad busca que cada participante recuerde una vez en que su entrega a Dios fue cuestionada o minimizada por otros, y cómo respondió a esa crítica.\",\"El tema busca enseñar que la aprobación ajena no es el termómetro de una entrega verdadera a Cristo.\"]},{\"titulo\":\"Ungido para Siempre\",\"resumen\":\"Cerrando con la promesa de Jesús de que la historia de esta mujer se contaría \\\"dondequiera que se predique el Evangelio\\\", este tema envía a los participantes con la certeza de que un acto de entrega total, aunque parezca pequeño o privado, tiene un peso eterno.\",\"puntos\":[\"El rito final busca sellar simbólicamente el \\\"alabastro\\\" nombrado en el primer tema, entregándolo de forma concreta durante el retiro.\",\"El cierre busca enviar a cada participante a vivir una entrega sin cálculo, confiando en que Dios, y no la aprobación humana, es quien da valor eterno a lo entregado.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"alabastro-roto\",\"codigo\":\"JAIM-ALABASTROROTO\",\"derej_slug\":\"jaim\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Alabastro Roto\",\"subtitle\":null,\"summary\":\"Quebrar lo más valioso que tienes, sin calcularlo, es la forma más alta de decirle a Cristo que lo vale todo.\",\"season_slug\":\"cuaresma\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"JAIM-ALABASTROROTO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la mujer que unge a Jesús con perfume de nardo puro en Betania\",\"bloques\":[{\"title\":\"Romper el frasco, no solo abrirlo\",\"text\":\"A diferencia de perfumar poco a poco, la mujer de Betania rompe de un solo golpe el cuello del alabastro: no hay marcha atrás ni cálculo posible. Un retiro sobre la entrega total, no la entrega medida.\"},{\"title\":\"Pieza intensa, con confesión disponible\",\"text\":\"Por la profundidad emocional y espiritual del contenido —quiebre, vergüenza, entrega radical—, este retiro contempla un sacerdote disponible para confesión durante todo el evento, no solo al cierre.\"}],\"temas\":[{\"titulo\":\"Preparar el Alabastro\",\"resumen\":\"A partir del valor del perfume de nardo puro —cerca de un año de salario—, este tema invita a cada participante a nombrar su propio \\\"alabastro\\\": lo que más le cuesta soltar (tiempo, orgullo, control, una relación, una imagen).\",\"puntos\":[\"La actividad introductoria busca que cada participante identifique con honestidad qué es lo más valioso —no necesariamente material— que aún no ha puesto en manos de Cristo.\",\"El tema busca desmontar la idea de que entregarse a Dios empieza por dar lo que sobra: empieza por reconocer lo que de verdad cuesta.\"]},{\"titulo\":\"El Quiebre\",\"resumen\":\"Este tema contempla el gesto de romper el frasco frente a todos, sin pedir permiso ni justificarse, para mostrar que la entrega total no se negocia ni se explica ante la mirada ajena.\",\"puntos\":[\"La dinámica busca que los participantes experimenten, de forma simbólica, lo incómodo de un gesto de amor que a otros les puede parecer excesivo o vergonzoso.\",\"El tema busca liberar a cada uno del miedo al \\\"qué dirán\\\" cuando se trata de amar a Cristo sin medida.\"]},{\"titulo\":\"El Reproche y el Silencio de Ella\",\"resumen\":\"Frente a quienes la critican por \\\"desperdiciar\\\" el perfume, la mujer no se defiende ni se justifica — y es Jesús quien responde por ella: \\\"Ella hizo lo que pudo.\\\"\",\"puntos\":[\"La actividad busca que cada participante recuerde una vez en que su entrega a Dios fue cuestionada o minimizada por otros, y cómo respondió a esa crítica.\",\"El tema busca enseñar que la aprobación ajena no es el termómetro de una entrega verdadera a Cristo.\"]},{\"titulo\":\"Ungido para Siempre\",\"resumen\":\"Cerrando con la promesa de Jesús de que la historia de esta mujer se contaría \\\"dondequiera que se predique el Evangelio\\\", este tema envía a los participantes con la certeza de que un acto de entrega total, aunque parezca pequeño o privado, tiene un peso eterno.\",\"puntos\":[\"El rito final busca sellar simbólicamente el \\\"alabastro\\\" nombrado en el primer tema, entregándolo de forma concreta durante el retiro.\",\"El cierre busca enviar a cada participante a vivir una entrega sin cálculo, confiando en que Dios, y no la aprobación humana, es quien da valor eterno a lo entregado.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'alabastro-roto');
