  SELECT 'esclava-senor', 'MESHARET-ESCLAVASENOR', 'mesharet', 'taller', NULL, NULL, 'Esclava del Señor', NULL, 'La fuerza arrolladora de la obediencia.', 'adviento', NULL, NULL, 'retiro-esclava-senor.webp', 'proximamente', '{\"basadoEn\":\"María, madre de Jesús\",\"bloques\":[{\"title\":\"El \\\"Aquí estoy\\\" original\",\"text\":\"Ser \\\"esclava\\\" o siervo de Dios no es ser un tapete; es la muestra más grande de libertad y fortaleza. Es entregar el control absoluto a Quien sabe hacer las cosas mejor.\"},{\"title\":\"Servicio que incomoda\",\"text\":\"Profundizar en lo que implica un ministerio real. Entregarse al prójimo de una forma que desorganice tu vida para bien, imitando el servicio incondicional de María.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"esclava-senor\",\"codigo\":\"MESHARET-ESCLAVASENOR\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Esclava del Señor\",\"subtitle\":null,\"summary\":\"La fuerza arrolladora de la obediencia.\",\"season_slug\":\"adviento\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-esclava-senor.webp\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"María, madre de Jesús\",\"bloques\":[{\"title\":\"El \\\"Aquí estoy\\\" original\",\"text\":\"Ser \\\"esclava\\\" o siervo de Dios no es ser un tapete; es la muestra más grande de libertad y fortaleza. Es entregar el control absoluto a Quien sabe hacer las cosas mejor.\"},{\"title\":\"Servicio que incomoda\",\"text\":\"Profundizar en lo que implica un ministerio real. Entregarse al prójimo de una forma que desorganice tu vida para bien, imitando el servicio incondicional de María.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
