  SELECT 'sabios-oriente', 'MESHARET-SABIOSORIENTE', 'mesharet', 'taller', NULL, NULL, 'Sabios del Oriente', NULL, 'La sabiduría de dar lo mejor que tienes en la vida ordinaria.', 'adviento', NULL, NULL, 'retiro-sabios-oriente.webp', 'proximamente', '{\"basadoEn\":\"los Reyes Magos\",\"bloques\":[{\"title\":\"Los dones en el 2026\",\"text\":\"Ya no traemos oro, incienso y mirra; traemos nuestro tiempo, nuestra atención y nuestros recursos. Asimilar qué significa realmente ofrendar al prójimo hasta que cueste.\"},{\"title\":\"La estrella en el asfalto\",\"text\":\"Dejar de esperar zarzas ardientes y aprender a reconocer a Dios disfrazado en la monotonía de la vida diaria y en la necesidad del otro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"sabios-oriente\",\"codigo\":\"MESHARET-SABIOSORIENTE\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Sabios del Oriente\",\"subtitle\":null,\"summary\":\"La sabiduría de dar lo mejor que tienes en la vida ordinaria.\",\"season_slug\":\"adviento\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"retiro-sabios-oriente.webp\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"los Reyes Magos\",\"bloques\":[{\"title\":\"Los dones en el 2026\",\"text\":\"Ya no traemos oro, incienso y mirra; traemos nuestro tiempo, nuestra atención y nuestros recursos. Asimilar qué significa realmente ofrendar al prójimo hasta que cueste.\"},{\"title\":\"La estrella en el asfalto\",\"text\":\"Dejar de esperar zarzas ardientes y aprender a reconocer a Dios disfrazado en la monotonía de la vida diaria y en la necesidad del otro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
