  SELECT 'camino-belen', 'JAIM-CAMINOBELEN', 'jaim', 'hora_santa', NULL, NULL, 'Camino a Belén', NULL, 'Antes de llegar al pesebre, hay que atreverse a caminar en la oscuridad guiados por una promesa.', 'adviento', NULL, NULL, 'adoracion-camino-belen.jpg', 'publicado', '{\"basadoEn\":\"el camino de los pastores y los Reyes Magos hacia Belén\",\"bloques\":[{\"title\":\"La misma estrella, otro desierto\",\"text\":\"Como los magos, avanzamos por tramos donde no se ve el destino completo, solo el siguiente paso iluminado. Una noche de adoración para volver a ponerse en camino hacia Cristo presente en la Eucaristía.\"},{\"title\":\"Silencio antes del Gloria\",\"text\":\"Antes del anuncio a los pastores, hubo noche, frío y espera. Aprender a habitar la espera del Adviento sin llenarla de ruido.\"},{\"title\":\"Llegar con las manos vacías\",\"text\":\"Ni los pastores ni los magos llegaron con méritos, llegaron con hambre de encontrarlo. Adorar sin necesitar tener algo que ofrecer primero.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"camino-belen\",\"codigo\":\"JAIM-CAMINOBELEN\",\"derej_slug\":\"jaim\",\"tipo\":\"hora_santa\",\"paso\":null,\"tema_paso\":null,\"title\":\"Camino a Belén\",\"subtitle\":null,\"summary\":\"Antes de llegar al pesebre, hay que atreverse a caminar en la oscuridad guiados por una promesa.\",\"season_slug\":\"adviento\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"adoracion-camino-belen.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"el camino de los pastores y los Reyes Magos hacia Belén\",\"bloques\":[{\"title\":\"La misma estrella, otro desierto\",\"text\":\"Como los magos, avanzamos por tramos donde no se ve el destino completo, solo el siguiente paso iluminado. Una noche de adoración para volver a ponerse en camino hacia Cristo presente en la Eucaristía.\"},{\"title\":\"Silencio antes del Gloria\",\"text\":\"Antes del anuncio a los pastores, hubo noche, frío y espera. Aprender a habitar la espera del Adviento sin llenarla de ruido.\"},{\"title\":\"Llegar con las manos vacías\",\"text\":\"Ni los pastores ni los magos llegaron con méritos, llegaron con hambre de encontrarlo. Adorar sin necesitar tener algo que ofrecer primero.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'camino-belen');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'belen-retiro', 'JAIM-BELENRETIRO', 'jaim', 'retiro', NULL, NULL, 'Belén', NULL, 'Ser padre o madre es decir \"sí\" a un plan que casi nunca se entiende del todo, y sostenerlo de todas formas.', 'adviento', NULL, NULL, 'JAIM-BELENRETIRO.jpg', 'proximamente', '{\"basadoEn\":\"los llamados de María y José en el Evangelio de la Infancia\",\"bloques\":[{\"title\":\"\\\"Sí\\\", sin entender del todo\",\"text\":\"Un retiro que no se queda en el pesebre de Navidad: recorre las decisiones más difíciles de María y José —aceptar, proteger, dejar ir— como espejo de lo que significa hoy ser padre o madre.\"},{\"title\":\"Para quien ya carga a un hijo\",\"text\":\"Pensado para padres, madres, padrinos o tutores que viven de cerca el peso de formar a otra persona, especialmente quienes sienten que no logran entender del todo a sus hijos o temen no estar a la altura de esa tarea.\"}],\"temas\":[{\"titulo\":\"El Sí que no Entiende del Todo\",\"resumen\":\"A partir de la Anunciación a María, este tema muestra que la vocación de ser padre o madre casi nunca llega con el plan completo explicado: empieza con un \\\"sí\\\" dado en la oscuridad, antes de entender lo que costará.\",\"puntos\":[\"La actividad introductoria busca que cada padre o madre recuerde el momento en que aceptó esa vocación —embarazo, adopción, tutela— sin saber realmente en qué se estaba metiendo.\",\"El tema busca que reconozcan que la fe no elimina la incertidumbre de criar a un hijo: la sostiene en medio de ella.\"]},{\"titulo\":\"El Padre que Actúa sin Palabras\",\"resumen\":\"Basado en José, que no tiene una sola línea de diálogo registrada en el Evangelio pero cambia toda su vida al obedecer un sueño, este tema confronta a los padres con la tentación de medir su entrega en palabras y no en decisiones silenciosas y sostenidas.\",\"puntos\":[\"La actividad busca que los participantes reconozcan los actos silenciosos y poco reconocidos que sostienen a una familia, y que suelen pasar desapercibidos frente a los que sí se dicen en voz alta.\",\"El tema busca liberar a los padres —especialmente a los hombres— de la idea de que amar a un hijo se demuestra solo con discursos o grandes gestos visibles.\"]},{\"titulo\":\"Proteger y Ser Atravesado\",\"resumen\":\"Uniendo la huida a Egipto con la profecía de Simeón sobre la espada que atravesará el alma de María, este tema muestra que proteger de verdad a un hijo casi siempre exige riesgo, y que el amor a los hijos incluye, de antemano, la certeza de que va a doler.\",\"puntos\":[\"La dinámica busca que cada padre o madre nombre en voz baja el miedo concreto que habita en su corazón: por la salud, el futuro, las decisiones o la fe de su hijo.\",\"El tema busca sanar la idea de que un padre \\\"fuerte\\\" no debería sentir miedo o dolor por sus hijos: el miedo de José y el dolor profetizado a María no los hicieron peores padres.\"]},{\"titulo\":\"Dejar Ir sin Dejar de Buscar\",\"resumen\":\"A partir del Niño perdido y hallado en el templo, este tema confronta a los padres con la angustia de no entender del todo el llamado propio de sus hijos, y los invita a buscar sin ahogar, y a dejar crecer sin abandonar.\",\"puntos\":[\"La actividad busca que los participantes distingan, en casos concretos de su propia familia, entre proteger por amor y controlar por miedo.\",\"El tema busca que cada padre o madre haga las paces con la pregunta \\\"¿no sabían que tenía que estar en la casa de mi Padre?\\\": sus hijos, antes que nada, le pertenecen a Dios.\"]},{\"titulo\":\"Hagan lo que Él les Diga\",\"resumen\":\"Cerrando con las Bodas de Caná, este tema envía a los padres como intercesores confiados que, como María, no resuelven ellos mismos los problemas de sus hijos, sino que los dirigen siempre hacia Cristo.\",\"puntos\":[\"El rito final busca que cada padre o madre entregue simbólicamente a su hijo o hija —presente en el corazón, aunque no esté físicamente ahí— en las manos de Cristo.\",\"El cierre busca sellar el compromiso de ser, como María en Caná, quien intercede y confía, más que quien controla el resultado.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"Padres y madres\",\"Padres adoptivos\",\"Padrinos y tutores\",\"Abuelos con crianza activa\"],\"chipsLabel\":\"Para quién es este retiro\"}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"belen-retiro\",\"codigo\":\"JAIM-BELENRETIRO\",\"derej_slug\":\"jaim\",\"tipo\":\"retiro\",\"paso\":null,\"tema_paso\":null,\"title\":\"Belén\",\"subtitle\":null,\"summary\":\"Ser padre o madre es decir \\\"sí\\\" a un plan que casi nunca se entiende del todo, y sostenerlo de todas formas.\",\"season_slug\":\"adviento\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"JAIM-BELENRETIRO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"los llamados de María y José en el Evangelio de la Infancia\",\"bloques\":[{\"title\":\"\\\"Sí\\\", sin entender del todo\",\"text\":\"Un retiro que no se queda en el pesebre de Navidad: recorre las decisiones más difíciles de María y José —aceptar, proteger, dejar ir— como espejo de lo que significa hoy ser padre o madre.\"},{\"title\":\"Para quien ya carga a un hijo\",\"text\":\"Pensado para padres, madres, padrinos o tutores que viven de cerca el peso de formar a otra persona, especialmente quienes sienten que no logran entender del todo a sus hijos o temen no estar a la altura de esa tarea.\"}],\"temas\":[{\"titulo\":\"El Sí que no Entiende del Todo\",\"resumen\":\"A partir de la Anunciación a María, este tema muestra que la vocación de ser padre o madre casi nunca llega con el plan completo explicado: empieza con un \\\"sí\\\" dado en la oscuridad, antes de entender lo que costará.\",\"puntos\":[\"La actividad introductoria busca que cada padre o madre recuerde el momento en que aceptó esa vocación —embarazo, adopción, tutela— sin saber realmente en qué se estaba metiendo.\",\"El tema busca que reconozcan que la fe no elimina la incertidumbre de criar a un hijo: la sostiene en medio de ella.\"]},{\"titulo\":\"El Padre que Actúa sin Palabras\",\"resumen\":\"Basado en José, que no tiene una sola línea de diálogo registrada en el Evangelio pero cambia toda su vida al obedecer un sueño, este tema confronta a los padres con la tentación de medir su entrega en palabras y no en decisiones silenciosas y sostenidas.\",\"puntos\":[\"La actividad busca que los participantes reconozcan los actos silenciosos y poco reconocidos que sostienen a una familia, y que suelen pasar desapercibidos frente a los que sí se dicen en voz alta.\",\"El tema busca liberar a los padres —especialmente a los hombres— de la idea de que amar a un hijo se demuestra solo con discursos o grandes gestos visibles.\"]},{\"titulo\":\"Proteger y Ser Atravesado\",\"resumen\":\"Uniendo la huida a Egipto con la profecía de Simeón sobre la espada que atravesará el alma de María, este tema muestra que proteger de verdad a un hijo casi siempre exige riesgo, y que el amor a los hijos incluye, de antemano, la certeza de que va a doler.\",\"puntos\":[\"La dinámica busca que cada padre o madre nombre en voz baja el miedo concreto que habita en su corazón: por la salud, el futuro, las decisiones o la fe de su hijo.\",\"El tema busca sanar la idea de que un padre \\\"fuerte\\\" no debería sentir miedo o dolor por sus hijos: el miedo de José y el dolor profetizado a María no los hicieron peores padres.\"]},{\"titulo\":\"Dejar Ir sin Dejar de Buscar\",\"resumen\":\"A partir del Niño perdido y hallado en el templo, este tema confronta a los padres con la angustia de no entender del todo el llamado propio de sus hijos, y los invita a buscar sin ahogar, y a dejar crecer sin abandonar.\",\"puntos\":[\"La actividad busca que los participantes distingan, en casos concretos de su propia familia, entre proteger por amor y controlar por miedo.\",\"El tema busca que cada padre o madre haga las paces con la pregunta \\\"¿no sabían que tenía que estar en la casa de mi Padre?\\\": sus hijos, antes que nada, le pertenecen a Dios.\"]},{\"titulo\":\"Hagan lo que Él les Diga\",\"resumen\":\"Cerrando con las Bodas de Caná, este tema envía a los padres como intercesores confiados que, como María, no resuelven ellos mismos los problemas de sus hijos, sino que los dirigen siempre hacia Cristo.\",\"puntos\":[\"El rito final busca que cada padre o madre entregue simbólicamente a su hijo o hija —presente en el corazón, aunque no esté físicamente ahí— en las manos de Cristo.\",\"El cierre busca sellar el compromiso de ser, como María en Caná, quien intercede y confía, más que quien controla el resultado.\"]}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":[\"Padres y madres\",\"Padres adoptivos\",\"Padrinos y tutores\",\"Abuelos con crianza activa\"],\"chipsLabel\":\"Para quién es este retiro\"}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'belen-retiro');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'cenaculo', 'JAIM-CENACULO', 'jaim', 'hora_santa', NULL, NULL, 'Cenáculo', NULL, 'La noche en que Cristo decidió quedarse para siempre en pan y vino.', 'pascua', '[\"cuaresma\"]', NULL, 'adoracion-cenaculo.jpg', 'proximamente', '{\"basadoEn\":\"la institución de la Eucaristía en la Última Cena\",\"bloques\":[{\"title\":\"La despedida que no fue despedida\",\"text\":\"En la Última Cena, Jesús no se aleja: inventa una forma de quedarse. Adorar la Eucaristía como la respuesta de Dios a no dejarnos solos.\"},{\"title\":\"\\\"Hagan esto en memoria mía\\\"\",\"text\":\"No fue una sugerencia, fue un mandato que se repite en cada misa desde entonces. Entender la adoración como continuación de esa misma noche.\"},{\"title\":\"Del cenáculo al sagrario\",\"text\":\"La misma presencia que compartió mesa con los apóstoles está hoy en el sagrario, disponible y esperando. Aprender a entrar al cenáculo cada vez que entramos a la capilla.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"cenaculo\",\"codigo\":\"JAIM-CENACULO\",\"derej_slug\":\"jaim\",\"tipo\":\"hora_santa\",\"paso\":null,\"tema_paso\":null,\"title\":\"Cenáculo\",\"subtitle\":null,\"summary\":\"La noche en que Cristo decidió quedarse para siempre en pan y vino.\",\"season_slug\":\"pascua\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"adoracion-cenaculo.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la institución de la Eucaristía en la Última Cena\",\"bloques\":[{\"title\":\"La despedida que no fue despedida\",\"text\":\"En la Última Cena, Jesús no se aleja: inventa una forma de quedarse. Adorar la Eucaristía como la respuesta de Dios a no dejarnos solos.\"},{\"title\":\"\\\"Hagan esto en memoria mía\\\"\",\"text\":\"No fue una sugerencia, fue un mandato que se repite en cada misa desde entonces. Entender la adoración como continuación de esa misma noche.\"},{\"title\":\"Del cenáculo al sagrario\",\"text\":\"La misma presencia que compartió mesa con los apóstoles está hoy en el sagrario, disponible y esperando. Aprender a entrar al cenáculo cada vez que entramos a la capilla.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'cenaculo');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'carbon-encendido', 'MESHARET-PREDICADORES', 'mesharet', 'taller', NULL, NULL, 'El Carbón Encendido · Formación de Predicadores', NULL, 'Nadie tiene derecho a hablar en nombre de Dios por mérito propio: primero hay que dejarse purificar.', 'ordinario', NULL, NULL, 'MESHARET-PREDICADORES.jpg', 'proximamente', '{\"basadoEn\":\"el profeta Isaías (Is 6:1-8)\",\"bloques\":[{\"title\":\"Labios impuros\",\"text\":\"Isaías se sabe de \\\"labios impuros\\\" en medio de un pueblo de labios impuros, y aun así es enviado a hablar. Reconocer que ningún predicador se para en el ambón porque lo merece, sino porque fue llamado.\"},{\"title\":\"El carbón que quema para sanar\",\"text\":\"Un serafín toca sus labios con un carbón encendido antes de que pueda decir una sola palabra. Entender la purificación —confesión, oración, vida limpia— como el paso obligado antes de anunciar, no un trámite opcional.\"},{\"title\":\"\\\"Aquí estoy, envíame\\\"\",\"text\":\"Solo después de ser tocado por el fuego, Isaías se ofrece voluntario. Descubrir que la disposición a predicar nace de haber sido purificado primero, no de tener las mejores palabras.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"carbon-encendido\",\"codigo\":\"MESHARET-PREDICADORES\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"El Carbón Encendido · Formación de Predicadores\",\"subtitle\":null,\"summary\":\"Nadie tiene derecho a hablar en nombre de Dios por mérito propio: primero hay que dejarse purificar.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-PREDICADORES.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el profeta Isaías (Is 6:1-8)\",\"bloques\":[{\"title\":\"Labios impuros\",\"text\":\"Isaías se sabe de \\\"labios impuros\\\" en medio de un pueblo de labios impuros, y aun así es enviado a hablar. Reconocer que ningún predicador se para en el ambón porque lo merece, sino porque fue llamado.\"},{\"title\":\"El carbón que quema para sanar\",\"text\":\"Un serafín toca sus labios con un carbón encendido antes de que pueda decir una sola palabra. Entender la purificación —confesión, oración, vida limpia— como el paso obligado antes de anunciar, no un trámite opcional.\"},{\"title\":\"\\\"Aquí estoy, envíame\\\"\",\"text\":\"Solo después de ser tocado por el fuego, Isaías se ofrece voluntario. Descubrir que la disposición a predicar nace de haber sido purificado primero, no de tener las mejores palabras.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'carbon-encendido');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'brazos-no-se-cansan', 'MESHARET-INTERCESION', 'mesharet', 'taller', NULL, NULL, 'Los Brazos que no se Cansan · Intercesión y Oración', NULL, 'Interceder no es orar en solitario: es sostener los brazos de otro hasta que la batalla termine.', 'ordinario', NULL, NULL, 'MESHARET-INTERCESION.jpg', 'proximamente', '{\"basadoEn\":\"Moisés, Aarón y Hur (Éx 17:8-13)\",\"bloques\":[{\"title\":\"Los brazos que se cansan\",\"text\":\"Mientras Josué pelea en el valle, Moisés ora con los brazos en alto en la montaña — y sus brazos, como los de cualquiera, se cansan. Aceptar que ningún intercesor aguanta solo para siempre.\"},{\"title\":\"Aarón y Hur no oraron por él, lo sostuvieron\",\"text\":\"La solución no fue relevar a Moisés ni orar en su lugar: fue sostener físicamente sus brazos hasta la puesta del sol. Entender la intercesión de ministerio como sostener a otro, no sustituirlo.\"},{\"title\":\"Mientras haya brazos en alto, hay victoria\",\"text\":\"La batalla se ganaba o perdía según los brazos de Moisés estuvieran arriba o abajo. Vivir la certeza de que la oración sostenida en comunidad —no aislada— sí cambia lo que pasa en el valle.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"brazos-no-se-cansan\",\"codigo\":\"MESHARET-INTERCESION\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Los Brazos que no se Cansan · Intercesión y Oración\",\"subtitle\":null,\"summary\":\"Interceder no es orar en solitario: es sostener los brazos de otro hasta que la batalla termine.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-INTERCESION.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Moisés, Aarón y Hur (Éx 17:8-13)\",\"bloques\":[{\"title\":\"Los brazos que se cansan\",\"text\":\"Mientras Josué pelea en el valle, Moisés ora con los brazos en alto en la montaña — y sus brazos, como los de cualquiera, se cansan. Aceptar que ningún intercesor aguanta solo para siempre.\"},{\"title\":\"Aarón y Hur no oraron por él, lo sostuvieron\",\"text\":\"La solución no fue relevar a Moisés ni orar en su lugar: fue sostener físicamente sus brazos hasta la puesta del sol. Entender la intercesión de ministerio como sostener a otro, no sustituirlo.\"},{\"title\":\"Mientras haya brazos en alto, hay victoria\",\"text\":\"La batalla se ganaba o perdía según los brazos de Moisés estuvieran arriba o abajo. Vivir la certeza de que la oración sostenida en comunidad —no aislada— sí cambia lo que pasa en el valle.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'brazos-no-se-cansan');
