  SELECT 'altar-puerta-abierta', 'MESHARET-HOSPITALIDAD', 'mesharet', 'taller', NULL, NULL, 'El Altar de la Puerta Abierta · Hospitalidad', NULL, 'La persona que recibes en la puerta puede ser Cristo disfrazado de desconocido.', 'ordinario', NULL, NULL, 'MESHARET-HOSPITALIDAD.jpg', 'proximamente', '{\"basadoEn\":\"Abraham y los tres visitantes (Gn 18:1-8)\",\"bloques\":[{\"title\":\"Urgencia, no obligación\",\"text\":\"Abraham corre al encuentro de tres desconocidos, no camina hacia ellos. Aprender que la hospitalidad real se nota en la urgencia con la que recibimos, no en el mínimo cumplido por cortesía.\"},{\"title\":\"Dar lo mejor, no lo que sobra\",\"text\":\"Manda preparar el mejor becerro y el pan más fino para gente que ni siquiera conocía. Entender el servicio de recepción como una ofrenda de lo mejor que tienes, no de las sobras.\"},{\"title\":\"Sin saber a quién recibía\",\"text\":\"Abraham no sabía que recibía a Dios mismo; solo supo recibir bien. Descubrir que la hospitalidad no depende de reconocer primero al huésped importante: es un acto de fe antes que de simpatía.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"altar-puerta-abierta\",\"codigo\":\"MESHARET-HOSPITALIDAD\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"El Altar de la Puerta Abierta · Hospitalidad\",\"subtitle\":null,\"summary\":\"La persona que recibes en la puerta puede ser Cristo disfrazado de desconocido.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-HOSPITALIDAD.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Abraham y los tres visitantes (Gn 18:1-8)\",\"bloques\":[{\"title\":\"Urgencia, no obligación\",\"text\":\"Abraham corre al encuentro de tres desconocidos, no camina hacia ellos. Aprender que la hospitalidad real se nota en la urgencia con la que recibimos, no en el mínimo cumplido por cortesía.\"},{\"title\":\"Dar lo mejor, no lo que sobra\",\"text\":\"Manda preparar el mejor becerro y el pan más fino para gente que ni siquiera conocía. Entender el servicio de recepción como una ofrenda de lo mejor que tienes, no de las sobras.\"},{\"title\":\"Sin saber a quién recibía\",\"text\":\"Abraham no sabía que recibía a Dios mismo; solo supo recibir bien. Descubrir que la hospitalidad no depende de reconocer primero al huésped importante: es un acto de fe antes que de simpatía.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'altar-puerta-abierta');
