  SELECT 'casa-de-mi-padre', 'MESHARET-MONAGUILLOS', 'mesharet', 'taller', NULL, NULL, 'En la Casa de mi Padre · Monaguillos', NULL, 'El altar no es una tarea que se cumple: es la casa donde uno se siente en casa.', 'ordinario', NULL, NULL, 'MESHARET-MONAGUILLOS.jpg', 'proximamente', '{\"basadoEn\":\"el Niño Jesús en el Templo (Lc 2:41-49)\",\"bloques\":[{\"title\":\"\\\"¿No sabían que debía estar en la casa de mi Padre?\\\"\",\"text\":\"A sus doce años, Jesús no se queda en el Templo por obligación ni por accidente: se queda porque ahí está en casa. Ayudar a que cada monaguillo sienta el altar como propio desde niño, no como un deber que se le asigna.\"},{\"title\":\"Servir sin dejar de ser niño\",\"text\":\"Jesús no deja de ser niño por estar entre los maestros; simplemente descubre temprano dónde pertenece. El servicio en el altar no exige madurar antes de tiempo: exige presencia y asombro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"casa-de-mi-padre\",\"codigo\":\"MESHARET-MONAGUILLOS\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"En la Casa de mi Padre · Monaguillos\",\"subtitle\":null,\"summary\":\"El altar no es una tarea que se cumple: es la casa donde uno se siente en casa.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-MONAGUILLOS.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el Niño Jesús en el Templo (Lc 2:41-49)\",\"bloques\":[{\"title\":\"\\\"¿No sabían que debía estar en la casa de mi Padre?\\\"\",\"text\":\"A sus doce años, Jesús no se queda en el Templo por obligación ni por accidente: se queda porque ahí está en casa. Ayudar a que cada monaguillo sienta el altar como propio desde niño, no como un deber que se le asigna.\"},{\"title\":\"Servir sin dejar de ser niño\",\"text\":\"Jesús no deja de ser niño por estar entre los maestros; simplemente descubre temprano dónde pertenece. El servicio en el altar no exige madurar antes de tiempo: exige presencia y asombro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'casa-de-mi-padre');
