  SELECT 'lo-que-oiste-de-mi', 'MESHARET-CATEQUISTAS', 'mesharet', 'taller', NULL, NULL, 'Lo que Oíste de Mí, Encomiéndalo · Catequistas', NULL, 'Enseñar la fe no es dar opinión propia: es custodiar y entregar fielmente lo que se recibió.', 'ordinario', NULL, NULL, 'MESHARET-CATEQUISTAS.jpg', 'proximamente', '{\"basadoEn\":\"Pablo y Timoteo (2 Tim 2:1-2)\",\"bloques\":[{\"title\":\"Una cadena, no una invención\",\"text\":\"Pablo no le pide a Timoteo que invente doctrina nueva, sino que transmita lo que oyó de él a otros que a su vez sabrán enseñar a otros. Entender la catequesis como eslabón de una cadena viva, no como espacio para la opinión personal.\"},{\"title\":\"Custodiar antes de entregar\",\"text\":\"Solo se puede encomendar con fidelidad lo que primero se guardó con cuidado. Vivir la formación del catequista como un proceso de custodiar el depósito de la fe antes de enseñarlo.\"},{\"title\":\"Hombres fieles capaces de enseñar a otros\",\"text\":\"El objetivo final no es que Timoteo enseñe bien, sino que forme a quienes también sabrán enseñar. Descubrir que un buen catequista multiplica catequistas, no solo transmite contenidos.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"lo-que-oiste-de-mi\",\"codigo\":\"MESHARET-CATEQUISTAS\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Lo que Oíste de Mí, Encomiéndalo · Catequistas\",\"subtitle\":null,\"summary\":\"Enseñar la fe no es dar opinión propia: es custodiar y entregar fielmente lo que se recibió.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-CATEQUISTAS.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Pablo y Timoteo (2 Tim 2:1-2)\",\"bloques\":[{\"title\":\"Una cadena, no una invención\",\"text\":\"Pablo no le pide a Timoteo que invente doctrina nueva, sino que transmita lo que oyó de él a otros que a su vez sabrán enseñar a otros. Entender la catequesis como eslabón de una cadena viva, no como espacio para la opinión personal.\"},{\"title\":\"Custodiar antes de entregar\",\"text\":\"Solo se puede encomendar con fidelidad lo que primero se guardó con cuidado. Vivir la formación del catequista como un proceso de custodiar el depósito de la fe antes de enseñarlo.\"},{\"title\":\"Hombres fieles capaces de enseñar a otros\",\"text\":\"El objetivo final no es que Timoteo enseñe bien, sino que forme a quienes también sabrán enseñar. Descubrir que un buen catequista multiplica catequistas, no solo transmite contenidos.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'lo-que-oiste-de-mi');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'manos-llenas-espiritu', 'MESHARET-BETSALEL', 'mesharet', 'taller', NULL, NULL, 'Manos Llenas del Espíritu · Betsalel', NULL, 'El trabajo técnico hecho con excelencia también es ministerio ungido, no apoyo secundario.', 'ordinario', NULL, NULL, 'MESHARET-BETSALEL.jpg', 'proximamente', '{\"basadoEn\":\"Betsalel (Éx 31:1-11)\",\"bloques\":[{\"title\":\"Lleno del Espíritu para tallar y construir\",\"text\":\"Dios no llena a Betsalel del Espíritu para profetizar, sino para diseñar, tallar y construir el Tabernáculo con sus propias manos. Reconocer que el talento técnico y artístico también es un don que Dios llena de sí mismo.\"},{\"title\":\"El servidor que nadie ve\",\"text\":\"Sonido, decoración, logística, diseño gráfico: el trabajo detrás de cámaras rara vez recibe aplausos, pero sostiene todo lo visible. Dar a estos servidores un lugar bíblico propio, no un rol \\\"de apoyo\\\".\"},{\"title\":\"Excelencia como acto de adoración\",\"text\":\"Betsalel no improvisó ni entregó lo mínimo: puso su mejor técnica al servicio del encuentro con Dios. Entender que hacer bien el trabajo técnico, con cuidado y detalle, también es una forma de adorar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"manos-llenas-espiritu\",\"codigo\":\"MESHARET-BETSALEL\",\"derej_slug\":\"mesharet\",\"tipo\":\"taller\",\"paso\":null,\"tema_paso\":null,\"title\":\"Manos Llenas del Espíritu · Betsalel\",\"subtitle\":null,\"summary\":\"El trabajo técnico hecho con excelencia también es ministerio ungido, no apoyo secundario.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"MESHARET-BETSALEL.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Betsalel (Éx 31:1-11)\",\"bloques\":[{\"title\":\"Lleno del Espíritu para tallar y construir\",\"text\":\"Dios no llena a Betsalel del Espíritu para profetizar, sino para diseñar, tallar y construir el Tabernáculo con sus propias manos. Reconocer que el talento técnico y artístico también es un don que Dios llena de sí mismo.\"},{\"title\":\"El servidor que nadie ve\",\"text\":\"Sonido, decoración, logística, diseño gráfico: el trabajo detrás de cámaras rara vez recibe aplausos, pero sostiene todo lo visible. Dar a estos servidores un lugar bíblico propio, no un rol \\\"de apoyo\\\".\"},{\"title\":\"Excelencia como acto de adoración\",\"text\":\"Betsalel no improvisó ni entregó lo mínimo: puso su mejor técnica al servicio del encuentro con Dios. Entender que hacer bien el trabajo técnico, con cuidado y detalle, también es una forma de adorar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'manos-llenas-espiritu');
