  SELECT 'barca-de-pedro', 'SIMJA-BARCADEPEDRO', 'simja', 'estaciones', NULL, NULL, 'La Barca de Pedro', NULL, 'Aunque no encuentres nada por tus propias fuerzas, si confías en Jesús la red se llena.', 'ordinario', NULL, 'primaria', 'SIMJA-BARCADEPEDRO.jpg', 'proximamente', '{\"basadoEn\":\"la pesca milagrosa de Pedro (Lc 5:1-11)\",\"bloques\":[{\"title\":\"Un pececito cuenta la historia\",\"text\":\"Un pececito narrador que \\\"vivió\\\" la pesca milagrosa guía a los niños en primera persona: Pedro pescó toda la noche sin sacar nada, hasta que hizo caso a Jesús y tiró la red una vez más.\"},{\"title\":\"Redes, peces y una barca de cartón\",\"text\":\"Estación física de pesca con red y peces de tela dentro de una \\\"barca\\\" armada en el salón, manualidad de un pez con un mensaje adentro, y cuento dramatizado del milagro, cerrando con un encuentro breve ante Jesús Eucaristía (\\\"Ven y sígueme\\\").\"},{\"title\":\"Puente con Dérej Oz\",\"text\":\"El mismo pasaje se retoma después, más profundo, en el taller OZ-Pedro para jóvenes: el niño que vive esta historia en Simjá puede reencontrarla al crecer.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"barca-de-pedro\",\"codigo\":\"SIMJA-BARCADEPEDRO\",\"derej_slug\":\"simja\",\"tipo\":\"estaciones\",\"paso\":null,\"tema_paso\":null,\"title\":\"La Barca de Pedro\",\"subtitle\":null,\"summary\":\"Aunque no encuentres nada por tus propias fuerzas, si confías en Jesús la red se llena.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":\"primaria\",\"cover\":\"SIMJA-BARCADEPEDRO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la pesca milagrosa de Pedro (Lc 5:1-11)\",\"bloques\":[{\"title\":\"Un pececito cuenta la historia\",\"text\":\"Un pececito narrador que \\\"vivió\\\" la pesca milagrosa guía a los niños en primera persona: Pedro pescó toda la noche sin sacar nada, hasta que hizo caso a Jesús y tiró la red una vez más.\"},{\"title\":\"Redes, peces y una barca de cartón\",\"text\":\"Estación física de pesca con red y peces de tela dentro de una \\\"barca\\\" armada en el salón, manualidad de un pez con un mensaje adentro, y cuento dramatizado del milagro, cerrando con un encuentro breve ante Jesús Eucaristía (\\\"Ven y sígueme\\\").\"},{\"title\":\"Puente con Dérej Oz\",\"text\":\"El mismo pasaje se retoma después, más profundo, en el taller OZ-Pedro para jóvenes: el niño que vive esta historia en Simjá puede reencontrarla al crecer.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'barca-de-pedro');
