  SELECT 'arca-de-noe', 'SIMJA-ARCADENOE', 'simja', 'estaciones', NULL, NULL, 'El Arca de Noé: Refugio Seguro', NULL, 'Dios cuida de mí y cumple sus promesas.', 'ordinario', NULL, 'kinder', 'SIMJA-ARCADENOE.jpg', 'proximamente', '{\"basadoEn\":\"Noé y la promesa del arcoíris (Gn 6-9, versión simplificada)\",\"bloques\":[{\"title\":\"Una paloma trae la rama de olivo\",\"text\":\"Una paloma guía a los niños de kínder por la historia sin entrar en juicio ni abstracciones sobre el pecado: solo el cuidado de Dios y la promesa concreta del arcoíris.\"},{\"title\":\"Animalitos de dos en dos y un arcoíris de manos\",\"text\":\"Clasificar animalitos de peluche \\\"de dos en dos\\\", pintura de manos formando un arcoíris, canto con movimientos, y cierre con una oración sencilla de agradecimiento.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"arca-de-noe\",\"codigo\":\"SIMJA-ARCADENOE\",\"derej_slug\":\"simja\",\"tipo\":\"estaciones\",\"paso\":null,\"tema_paso\":null,\"title\":\"El Arca de Noé: Refugio Seguro\",\"subtitle\":null,\"summary\":\"Dios cuida de mí y cumple sus promesas.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":\"kinder\",\"cover\":\"SIMJA-ARCADENOE.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Noé y la promesa del arcoíris (Gn 6-9, versión simplificada)\",\"bloques\":[{\"title\":\"Una paloma trae la rama de olivo\",\"text\":\"Una paloma guía a los niños de kínder por la historia sin entrar en juicio ni abstracciones sobre el pecado: solo el cuidado de Dios y la promesa concreta del arcoíris.\"},{\"title\":\"Animalitos de dos en dos y un arcoíris de manos\",\"text\":\"Clasificar animalitos de peluche \\\"de dos en dos\\\", pintura de manos formando un arcoíris, canto con movimientos, y cierre con una oración sencilla de agradecimiento.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'arca-de-noe');
