  SELECT 'buen-pastor-ovejita-perdida', 'SIMJA-BUENPASTOR', 'simja', 'estaciones', NULL, NULL, 'El Buen Pastor y la Ovejita Perdida', NULL, 'La Iglesia nunca deja de buscar a nadie.', 'ordinario', NULL, 'ambos', 'SIMJA-BUENPASTOR.jpg', 'proximamente', '{\"basadoEn\":\"la parábola de la oveja perdida (Lc 15:3-7)\",\"bloques\":[{\"title\":\"Talia, la ovejita que se pierde\",\"text\":\"Talia se aleja del rebaño y es buscada sin descanso — la imagen que un niño entiende sin ninguna traducción conceptual: el miedo de perderse y la alegría de ser encontrado.\"},{\"title\":\"Buscar, tejer y ser cargado\",\"text\":\"Juego de \\\"buscar la oveja perdida\\\" escondida en el espacio, manualidad de una ovejita de algodón, dramatización con títeres del pastor buscando, y cierre donde cada niño \\\"es cargado\\\" simbólicamente sobre los hombros del pastor.\"},{\"title\":\"Un gancho para el que se siente lejos\",\"text\":\"Ideal también con niños que vienen de familias alejadas de la fe o en procesos de primera comunión: nadie es demasiado pequeño ni está demasiado lejos para que lo busquen.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"buen-pastor-ovejita-perdida\",\"codigo\":\"SIMJA-BUENPASTOR\",\"derej_slug\":\"simja\",\"tipo\":\"estaciones\",\"paso\":null,\"tema_paso\":null,\"title\":\"El Buen Pastor y la Ovejita Perdida\",\"subtitle\":null,\"summary\":\"La Iglesia nunca deja de buscar a nadie.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":\"ambos\",\"cover\":\"SIMJA-BUENPASTOR.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la parábola de la oveja perdida (Lc 15:3-7)\",\"bloques\":[{\"title\":\"Talia, la ovejita que se pierde\",\"text\":\"Talia se aleja del rebaño y es buscada sin descanso — la imagen que un niño entiende sin ninguna traducción conceptual: el miedo de perderse y la alegría de ser encontrado.\"},{\"title\":\"Buscar, tejer y ser cargado\",\"text\":\"Juego de \\\"buscar la oveja perdida\\\" escondida en el espacio, manualidad de una ovejita de algodón, dramatización con títeres del pastor buscando, y cierre donde cada niño \\\"es cargado\\\" simbólicamente sobre los hombros del pastor.\"},{\"title\":\"Un gancho para el que se siente lejos\",\"text\":\"Ideal también con niños que vienen de familias alejadas de la fe o en procesos de primera comunión: nadie es demasiado pequeño ni está demasiado lejos para que lo busquen.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'buen-pastor-ovejita-perdida');
