  SELECT 'cinco-panes-dos-peces', 'SIMJA-CINCOPANES', 'simja', 'estaciones', NULL, NULL, 'Los Cinco Panes y Dos Peces', NULL, 'Lo poco que tengo, puesto en manos de Jesús, alcanza para todos.', 'ordinario', NULL, 'primaria', 'SIMJA-CINCOPANES.jpg', 'proximamente', '{\"basadoEn\":\"la multiplicación de los panes (Jn 6:1-13)\",\"bloques\":[{\"title\":\"El niño que compartió su almuerzo\",\"text\":\"Es la única historia bíblica donde el protagonista es literalmente un niño: quien participa se identifica de forma directa con él, no solo lo observa.\"},{\"title\":\"Canasta de pan y reparto real\",\"text\":\"Manualidad de una \\\"canasta de panes\\\", juego de repartir algo (dulces, estampas) entre todo el grupo, cuento dramatizado, y cierre con reparto real de un pan bendecido.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"cinco-panes-dos-peces\",\"codigo\":\"SIMJA-CINCOPANES\",\"derej_slug\":\"simja\",\"tipo\":\"estaciones\",\"paso\":null,\"tema_paso\":null,\"title\":\"Los Cinco Panes y Dos Peces\",\"subtitle\":null,\"summary\":\"Lo poco que tengo, puesto en manos de Jesús, alcanza para todos.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":\"primaria\",\"cover\":\"SIMJA-CINCOPANES.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la multiplicación de los panes (Jn 6:1-13)\",\"bloques\":[{\"title\":\"El niño que compartió su almuerzo\",\"text\":\"Es la única historia bíblica donde el protagonista es literalmente un niño: quien participa se identifica de forma directa con él, no solo lo observa.\"},{\"title\":\"Canasta de pan y reparto real\",\"text\":\"Manualidad de una \\\"canasta de panes\\\", juego de repartir algo (dulces, estampas) entre todo el grupo, cuento dramatizado, y cierre con reparto real de un pan bendecido.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'cinco-panes-dos-peces');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'zaqueo-simja', 'SIMJA-ZAQUEO', 'simja', 'estaciones', NULL, NULL, 'Zaqueo se Sube al Árbol', NULL, 'Aunque seas pequeño y nadie te vea, Jesús te busca y te llama por tu nombre.', 'ordinario', NULL, 'primaria', 'SIMJA-ZAQUEO.jpg', 'proximamente', '{\"basadoEn\":\"Zaqueo, el publicano de Jericó (Lc 19:1-10)\",\"bloques\":[{\"title\":\"\\\"Yo era chiquito, como ustedes\\\"\",\"text\":\"Zaqueo se narra en primera persona por su estatura, la misma que conecta literalmente con la de un niño que a menudo se siente \\\"el chiquito\\\" en su familia o grupo.\"},{\"title\":\"Trepar para ver mejor\",\"text\":\"Trepar con seguridad a una estructura tipo \\\"árbol\\\" para \\\"ver mejor\\\", manualidad de un árbol con el nombre propio en una hoja, y cierre donde el facilitador llama a cada niño por su nombre.\"},{\"title\":\"Puente con Dérej Oz\",\"text\":\"La misma figura ya tiene su propio taller en OZ-Zaqueo para jóvenes (\\\"no hace falta que te vean para que Cristo te llame por tu nombre\\\") — misma coherencia vertical que ya conecta Simjá y Oz a través de Pedro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"zaqueo-simja\",\"codigo\":\"SIMJA-ZAQUEO\",\"derej_slug\":\"simja\",\"tipo\":\"estaciones\",\"paso\":null,\"tema_paso\":null,\"title\":\"Zaqueo se Sube al Árbol\",\"subtitle\":null,\"summary\":\"Aunque seas pequeño y nadie te vea, Jesús te busca y te llama por tu nombre.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":\"primaria\",\"cover\":\"SIMJA-ZAQUEO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Zaqueo, el publicano de Jericó (Lc 19:1-10)\",\"bloques\":[{\"title\":\"\\\"Yo era chiquito, como ustedes\\\"\",\"text\":\"Zaqueo se narra en primera persona por su estatura, la misma que conecta literalmente con la de un niño que a menudo se siente \\\"el chiquito\\\" en su familia o grupo.\"},{\"title\":\"Trepar para ver mejor\",\"text\":\"Trepar con seguridad a una estructura tipo \\\"árbol\\\" para \\\"ver mejor\\\", manualidad de un árbol con el nombre propio en una hoja, y cierre donde el facilitador llama a cada niño por su nombre.\"},{\"title\":\"Puente con Dérej Oz\",\"text\":\"La misma figura ya tiene su propio taller en OZ-Zaqueo para jóvenes (\\\"no hace falta que te vean para que Cristo te llame por tu nombre\\\") — misma coherencia vertical que ya conecta Simjá y Oz a través de Pedro.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'zaqueo-simja');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'emaus', 'OZ-EMAUS', 'oz', 'taller', 8, NULL, 'Emaús', NULL, 'La oración no es un monólogo: es el camino en que Jesús nos alcanza, camina con nosotros y se nos revela partiendo el pan.', 'pascua', NULL, NULL, 'OZ-EMAUS.jpg', 'publicado', '{\"basadoEn\":\"los discípulos de Emaús\",\"bloques\":[{\"title\":\"Un acercamiento amistoso a la oración\",\"text\":\"Un taller práctico para descubrir tres formas concretas de orar —petición, acción de gracias e intercesión— y sembrar una relación constante con Dios.\"},{\"title\":\"Para quien empieza o retoma el camino\",\"text\":\"Pensado para jóvenes que no han profundizado en su fe o que han puesto en pausa su caminar con Cristo, con al menos un sacramental recibido.\"}],\"temas\":[{\"titulo\":\"Camino de Emaús\",\"resumen\":\"A partir del relato de los discípulos de Emaús, este tema muestra que no reconocer a Jesús no depende de los ojos sino del corazón cerrado, y que basta abrirse al diálogo y al partir del pan para descubrir su presencia real.\",\"puntos\":[\"La actividad introductoria busca que los jóvenes experimenten, sin poder ver, que reconocer al otro —y a Jesús— depende de algo más que la vista.\",\"El tema busca llevar a cada joven a reconocer que la oración no es un monólogo, sino un encuentro real que, una vez vivido, impulsa a compartirlo con otros.\"],\"evocacion\":\"Lc 24:13-16 — dos discípulos caminan hacia Emaús discutiendo lo sucedido; Jesús se les acerca y camina con ellos, pero \\\"tenían los ojos incapacitados para reconocerlo\\\".\",\"actividadIntroductoria\":\"Actividad previa \\\"Encuentra a tu equipo\\\": en círculo concéntrico, los chicos se vendan los ojos, dan un paso a la derecha y deben identificar con quién conversan sin preguntar directamente quién es, en rondas de dos minutos, cambiando de pareja tres veces.\",\"contenido\":\"Se medita el pasaje de Emaús en cuatro partes (Lc 24:13-16, 17-24, 28-32, 33-35), estableciendo un paralelismo entre la actividad vendados y la ceguera de los discípulos: no reconocer a Jesús no depende solo de la vista, sino de los oídos y el cuerpo cerrados a sentir su presencia. Jesús pregunta no porque ignore lo sucedido, sino porque le interesa que se lo cuenten personalmente. Al partirse el pan \\\"se les abrieron los ojos\\\", y de inmediato salen a anunciarlo — la oración no es un monólogo, es un encuentro real que se comparte.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Vendas o rectángulos de tela (la ceguera que se convierte en encuentro)\"],\"reflexion\":\"\\\"¿No sentíamos arder nuestro corazón mientras nos hablaba por el camino?\\\" — el ardor del corazón como señal de una presencia real, aunque no se vea ni se escuche con los sentidos.\"},{\"titulo\":\"Alianza Nueva — Analogía\",\"resumen\":\"Mediante la analogía del llanto a solas que termina en consuelo, este tema ayuda a los jóvenes a reconocer sus propias dificultades para orar y a descubrir que la necesidad de ser consolado es, en sí misma, una forma de oración.\",\"puntos\":[\"La dinámica de las premisas busca que cada joven identifique con honestidad sus propias barreras para orar: no saber qué decir, sentir que Dios no responde, distraerse.\",\"La actividad del globo busca que cada joven entregue simbólicamente esa dificultad, confiando en que su oración —por sencilla que sea— será escuchada.\"],\"evocacion\":\"Momento de conectar lo vivido por los peregrinos de Emaús con la propia experiencia de dolor, sufrimiento o soledad de cada joven.\",\"actividadIntroductoria\":null,\"contenido\":\"Analogía de llorar a solas en la habitación con la puerta cerrada: el llanto que parece no tener respuesta, hasta que —sin darnos cuenta— el corazón se calma y ese calor que queda no es dolor sino consuelo. Ese consuelo es Jesús, que se acerca incluso cuando más solos pensamos estar (Mt 6:6). La necesidad tan natural de ser consolado es ya, en sí misma, una oración.\",\"actividadesAdicionales\":\"Actividades reflexivas: los chicos cierran los ojos y levantan la mano si se identifican con 8 premisas sobre su experiencia de oración (les cuesta iniciar/terminar, no saben qué decir, se disocian, sienten que no responde, etc.). Después escriben en post-its lo que el tema les exhorta a expresar, los meten en un globo dorado y lo inflan.\",\"simbolos\":[\"Globo dorado con post-its dentro (la oración que se guarda y se entrega)\",\"Post-its y plumas\"],\"reflexion\":\"\\\"Cada latido de tu corazón es un te amo de Dios\\\" — cuando no se siente nada al orar, basta con sentir el propio corazón para saber que Él está presente y acompaña.\"},{\"titulo\":\"Eucaristía de Emaús\",\"resumen\":\"Este cierre invita a los jóvenes a vivir la oración como un diálogo real con Dios a través de la Palabra, entregando lo vivido en el taller y comprometiéndose a sostener la nueva alianza formada con Cristo.\",\"puntos\":[\"La dinámica de abrir la Biblia al azar busca que cada joven experimente la oración como una conversación viva, donde Dios responde de forma concreta y personal.\",\"El cierre en grupo busca sellar el compromiso de que la nueva relación con Cristo iniciada en el taller permanezca y se sostenga en el tiempo.\"],\"evocacion\":\"De pie y en círculo, se invoca al Espíritu Santo como quien impulsa a orar, no solo a hablar en soledad.\",\"actividadIntroductoria\":\"Al centro se coloca una caja grande de regalo dorada; cada joven entrega su oración (el globo) confiando en que será escuchada. Quienes quieran profundizar pueden acercarse a un grupo de intercesores.\",\"contenido\":\"Se preparan biblias para cada participante, quienes al querer una respuesta dicen \\\"Habla Padre que tu hijo/hija te escucha\\\" y abren la Biblia donde su corazón les dicte, leyendo el pasaje que más les llame la atención — vivencia de la oración como diálogo real, no monólogo.\",\"actividadesAdicionales\":\"Compartir en grupo la experiencia del taller y cerrar con oración final de acción de gracias, pidiendo que la nueva alianza formada con Cristo perdure.\",\"simbolos\":[\"Caja grande de regalo dorada (la entrega de la oración)\",\"Biblias abiertas al azar (la Palabra como respuesta viva)\"],\"reflexion\":\"Retomando a San Agustín: \\\"Nuestro corazón está inquieto mientras no descanse en ti\\\" — la oración es tener una relación con Jesús, no un monólogo.\"}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"emaus\",\"codigo\":\"OZ-EMAUS\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":8,\"tema_paso\":null,\"title\":\"Emaús\",\"subtitle\":null,\"summary\":\"La oración no es un monólogo: es el camino en que Jesús nos alcanza, camina con nosotros y se nos revela partiendo el pan.\",\"season_slug\":\"pascua\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-EMAUS.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"los discípulos de Emaús\",\"bloques\":[{\"title\":\"Un acercamiento amistoso a la oración\",\"text\":\"Un taller práctico para descubrir tres formas concretas de orar —petición, acción de gracias e intercesión— y sembrar una relación constante con Dios.\"},{\"title\":\"Para quien empieza o retoma el camino\",\"text\":\"Pensado para jóvenes que no han profundizado en su fe o que han puesto en pausa su caminar con Cristo, con al menos un sacramental recibido.\"}],\"temas\":[{\"titulo\":\"Camino de Emaús\",\"resumen\":\"A partir del relato de los discípulos de Emaús, este tema muestra que no reconocer a Jesús no depende de los ojos sino del corazón cerrado, y que basta abrirse al diálogo y al partir del pan para descubrir su presencia real.\",\"puntos\":[\"La actividad introductoria busca que los jóvenes experimenten, sin poder ver, que reconocer al otro —y a Jesús— depende de algo más que la vista.\",\"El tema busca llevar a cada joven a reconocer que la oración no es un monólogo, sino un encuentro real que, una vez vivido, impulsa a compartirlo con otros.\"],\"evocacion\":\"Lc 24:13-16 — dos discípulos caminan hacia Emaús discutiendo lo sucedido; Jesús se les acerca y camina con ellos, pero \\\"tenían los ojos incapacitados para reconocerlo\\\".\",\"actividadIntroductoria\":\"Actividad previa \\\"Encuentra a tu equipo\\\": en círculo concéntrico, los chicos se vendan los ojos, dan un paso a la derecha y deben identificar con quién conversan sin preguntar directamente quién es, en rondas de dos minutos, cambiando de pareja tres veces.\",\"contenido\":\"Se medita el pasaje de Emaús en cuatro partes (Lc 24:13-16, 17-24, 28-32, 33-35), estableciendo un paralelismo entre la actividad vendados y la ceguera de los discípulos: no reconocer a Jesús no depende solo de la vista, sino de los oídos y el cuerpo cerrados a sentir su presencia. Jesús pregunta no porque ignore lo sucedido, sino porque le interesa que se lo cuenten personalmente. Al partirse el pan \\\"se les abrieron los ojos\\\", y de inmediato salen a anunciarlo — la oración no es un monólogo, es un encuentro real que se comparte.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Vendas o rectángulos de tela (la ceguera que se convierte en encuentro)\"],\"reflexion\":\"\\\"¿No sentíamos arder nuestro corazón mientras nos hablaba por el camino?\\\" — el ardor del corazón como señal de una presencia real, aunque no se vea ni se escuche con los sentidos.\"},{\"titulo\":\"Alianza Nueva — Analogía\",\"resumen\":\"Mediante la analogía del llanto a solas que termina en consuelo, este tema ayuda a los jóvenes a reconocer sus propias dificultades para orar y a descubrir que la necesidad de ser consolado es, en sí misma, una forma de oración.\",\"puntos\":[\"La dinámica de las premisas busca que cada joven identifique con honestidad sus propias barreras para orar: no saber qué decir, sentir que Dios no responde, distraerse.\",\"La actividad del globo busca que cada joven entregue simbólicamente esa dificultad, confiando en que su oración —por sencilla que sea— será escuchada.\"],\"evocacion\":\"Momento de conectar lo vivido por los peregrinos de Emaús con la propia experiencia de dolor, sufrimiento o soledad de cada joven.\",\"actividadIntroductoria\":null,\"contenido\":\"Analogía de llorar a solas en la habitación con la puerta cerrada: el llanto que parece no tener respuesta, hasta que —sin darnos cuenta— el corazón se calma y ese calor que queda no es dolor sino consuelo. Ese consuelo es Jesús, que se acerca incluso cuando más solos pensamos estar (Mt 6:6). La necesidad tan natural de ser consolado es ya, en sí misma, una oración.\",\"actividadesAdicionales\":\"Actividades reflexivas: los chicos cierran los ojos y levantan la mano si se identifican con 8 premisas sobre su experiencia de oración (les cuesta iniciar/terminar, no saben qué decir, se disocian, sienten que no responde, etc.). Después escriben en post-its lo que el tema les exhorta a expresar, los meten en un globo dorado y lo inflan.\",\"simbolos\":[\"Globo dorado con post-its dentro (la oración que se guarda y se entrega)\",\"Post-its y plumas\"],\"reflexion\":\"\\\"Cada latido de tu corazón es un te amo de Dios\\\" — cuando no se siente nada al orar, basta con sentir el propio corazón para saber que Él está presente y acompaña.\"},{\"titulo\":\"Eucaristía de Emaús\",\"resumen\":\"Este cierre invita a los jóvenes a vivir la oración como un diálogo real con Dios a través de la Palabra, entregando lo vivido en el taller y comprometiéndose a sostener la nueva alianza formada con Cristo.\",\"puntos\":[\"La dinámica de abrir la Biblia al azar busca que cada joven experimente la oración como una conversación viva, donde Dios responde de forma concreta y personal.\",\"El cierre en grupo busca sellar el compromiso de que la nueva relación con Cristo iniciada en el taller permanezca y se sostenga en el tiempo.\"],\"evocacion\":\"De pie y en círculo, se invoca al Espíritu Santo como quien impulsa a orar, no solo a hablar en soledad.\",\"actividadIntroductoria\":\"Al centro se coloca una caja grande de regalo dorada; cada joven entrega su oración (el globo) confiando en que será escuchada. Quienes quieran profundizar pueden acercarse a un grupo de intercesores.\",\"contenido\":\"Se preparan biblias para cada participante, quienes al querer una respuesta dicen \\\"Habla Padre que tu hijo/hija te escucha\\\" y abren la Biblia donde su corazón les dicte, leyendo el pasaje que más les llame la atención — vivencia de la oración como diálogo real, no monólogo.\",\"actividadesAdicionales\":\"Compartir en grupo la experiencia del taller y cerrar con oración final de acción de gracias, pidiendo que la nueva alianza formada con Cristo perdure.\",\"simbolos\":[\"Caja grande de regalo dorada (la entrega de la oración)\",\"Biblias abiertas al azar (la Palabra como respuesta viva)\"],\"reflexion\":\"Retomando a San Agustín: \\\"Nuestro corazón está inquieto mientras no descanse en ti\\\" — la oración es tener una relación con Jesús, no un monólogo.\"}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'emaus');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'pedro', 'OZ-PEDRO', 'oz', 'taller', 4, NULL, 'Pedro, el discípulo firme', NULL, 'La fuerza no está en no caer, sino en dejarse llamar de nuevo cada vez que se cae.', 'pascua', '[\"cuaresma\"]', NULL, 'OZ-PEDRO.jpg', 'publicado', '{\"basadoEn\":\"Simón Pedro, apóstol\",\"bloques\":[{\"title\":\"El camino de Simón a Pedro\",\"text\":\"Recorre el antes, el durante y el después de ser renombrado Pedro, como espejo de seguimiento para los temperamentos jóvenes y las inseguridades en la fe.\"},{\"title\":\"Para quien se siente lejos\",\"text\":\"Pensado para jóvenes que buscan profundizar su fe, especialmente quienes se sienten solos, no escuchados por Dios, o que se han alejado de Él.\"}],\"temas\":[{\"titulo\":\"Encuentro\",\"resumen\":\"A partir de la pesca milagrosa, este tema muestra que el encuentro real con Jesús no espera a que estemos exitosos o preparados, sino que llega en medio del fracaso cotidiano.\",\"puntos\":[\"La dinámica de identificar al equipo por la voz busca que los jóvenes experimenten que reconocer a Jesús va más allá de lo evidente a los sentidos.\",\"El tema busca que cada joven reconozca que sus propios fracasos no son un obstáculo para el encuentro con Cristo, sino el lugar donde Él se hace presente.\"],\"evocacion\":\"Lc 5:1-5 — Jesús enseña a las multitudes desde la barca de Simón y le pide echar las redes en la parte más profunda, después de una noche entera sin pescar nada.\",\"actividadIntroductoria\":\"Dinámica \\\"Encuentra a tu equipo\\\": en equipos de máximo 4, uno vendado debe identificar a su equipo guiándose solo por los sonidos y gritos que hacen para orientarlo.\",\"contenido\":\"Pedro era un pescador de unos 20 años con responsabilidades familiares y religiosas. Había fracasado toda la noche en su oficio, y aun así, cuando un desconocido le pide volver a intentarlo, Simón —incrédulo— obedece \\\"porque tú lo pides\\\". El encuentro con Jesús ocurre precisamente en medio del fracaso cotidiano, no fuera de él.\",\"actividadesAdicionales\":null,\"simbolos\":[\"La venda de ojos (identificar por la voz, no por la vista — como reconocer a Jesús más allá de lo evidente)\"],\"reflexion\":\"El encuentro real con Jesús no espera a que estemos exitosos o preparados: llega en medio de la noche sin pesca.\"},{\"titulo\":\"Llamado\",\"resumen\":\"Este tema muestra que Jesús conoce por completo la historia de cada joven y, aun así, lo llama y lo transforma, dándole una nueva identidad y misión.\",\"puntos\":[\"La dinámica del dibujo transmitido busca que los jóvenes noten cómo una historia se distorsiona al pasar de mano en mano, para contrastarla con la historia que Dios sí transforma para bien.\",\"El tema busca que cada joven se reconozca llamado y renombrado por Dios más allá de su pasado, con la certeza de que todo pecador tiene un futuro.\"],\"evocacion\":\"Lc 5:6-11 y Mt 16:13-19 — la pesca milagrosa hunde las barcas; Simón cae a los pies de Jesús reconociéndose pecador, y Jesús responde: \\\"No temas, desde ahora serás pescador de hombres.\\\" Más tarde, ante la confesión \\\"Tú eres el Cristo\\\", Jesús le renombra Pedro.\",\"actividadIntroductoria\":\"Dinámica \\\"Teléfono descompuesto gráfico\\\": en fila, sin voltear, se transmite un dibujo simple dibujándolo con el dedo en la espalda del compañero de enfrente, hasta llegar al primero de la fila, quien lo reproduce en papel.\",\"contenido\":\"Jesús conoce el pasado, presente y futuro de Simón y aun así lo llama y lo transforma: \\\"tú eres Pedro y sobre esta piedra edificaré mi iglesia, y las fuerzas del infierno no prevalecerán sobre ella.\\\" Todo santo tiene un pasado, y todo pecador un futuro.\",\"actividadesAdicionales\":null,\"simbolos\":[\"El dibujo que se transforma (a veces se distorsiona) al pasar de mano en mano, como la propia historia que Dios transforma\"],\"reflexion\":\"Todo santo tiene un pasado, y todo pecador un futuro.\"},{\"titulo\":\"Pasión y Muerte\",\"resumen\":\"Este tema confronta a los jóvenes con la negación y el miedo de Pedro, para mostrar que reconocer la propia fragilidad no es una derrota, sino el punto exacto donde Jesús sigue mirando con amor.\",\"puntos\":[\"La dinámica del paliacate busca que los jóvenes experimenten de forma lúdica la fragilidad y la posibilidad de la caída que todos comparten.\",\"El tema busca que cada joven identifique sus propias negaciones o cobardías sin sentir que eso cierra la puerta a la mirada amorosa de Jesús.\"],\"evocacion\":\"Mt 16:21-27 y Mc 14:27-31 — Pedro reprende a Jesús por anunciar su propia pasión (\\\"¡Quítate de delante de mí, Satanás!\\\") y más tarde promete no negarlo jamás, aunque Jesús predice sus tres negaciones.\",\"actividadIntroductoria\":\"Dinámica \\\"Vidas individuales\\\": cada joven lleva un paliacate atorado en el pantalón; el objetivo es quitarle el paliacate a los demás sin perder el propio. Quien lo pierde, queda eliminado.\",\"contenido\":\"Jesús reconoce la dureza que aún vive en el corazón de Pedro. Tras la negación, el peso de haberle fallado y el recuerdo de la mirada de Jesús queman a Pedro. El miedo invade a los discípulos y se esconden; Pedro reconoce su humanidad y su falla, pero su corazón herido duda de la resurrección anunciada.\",\"actividadesAdicionales\":null,\"simbolos\":[\"El paliacate que se pierde (la fragilidad y la caída que todos compartimos)\"],\"reflexion\":\"Reconocer la propia fragilidad —como Pedro— no es el final: es el punto exacto donde Jesús sigue mirando con amor.\"},{\"titulo\":\"Resurrección\",\"resumen\":\"A través de las tres preguntas que Jesús hace a Pedro junto al lago, este tema muestra cómo el amor de Cristo sana y restaura lo que la propia debilidad rompió.\",\"puntos\":[\"La vivencia sensorial de la Pasión busca que los jóvenes se conecten corporalmente con el sufrimiento de Cristo antes de recibir el anuncio de su resurrección.\",\"El tema busca que cada joven reciba, como Pedro, la restauración del amor de Jesús frente a sus propias caídas, sin compararse con el camino de los demás.\"],\"evocacion\":\"Jn 21:15-22 — junto al lago, Jesús pregunta tres veces a Simón Pedro \\\"¿me amas?\\\", y tres veces lo confirma en la misión de apacentar sus ovejas.\",\"actividadIntroductoria\":\"Dinámica \\\"Pasión vivencial\\\": con los ojos vendados y música de fondo, los jóvenes caminan descalzos sobre piedras, se arrodillan, reciben una corona de espinas, sienten golpes simulados de flagelación y presión en las manos como los clavos, cerrando con un momento de oración ante un crucifijo.\",\"contenido\":\"Pedro, escondido por miedo, se llena de gozo al saber a Jesús resucitado. Las tres preguntas de Jesús (\\\"¿me amas?\\\") sanan las tres negaciones. Cuando Pedro se compara con Juan, Jesús lo devuelve a lo esencial: \\\"A ti qué te importa, ¡sígueme!\\\"\",\"actividadesAdicionales\":null,\"simbolos\":[\"Corona de espinas, golpes simulados, presión en las manos (la Pasión revivida en el cuerpo)\",\"Crucifijo para la oración final\"],\"reflexion\":\"Las tres preguntas de amor deshacen las tres negaciones — el amor de Jesús restaura lo que la propia debilidad rompió.\"},{\"titulo\":\"Envío\",\"resumen\":\"Este cierre cristaliza la misión concreta que Jesús confía a Pedro —apacentar, pastorear y anunciar— como horizonte al que cada joven también es enviado tras su propio proceso de encuentro y conversión.\",\"puntos\":[\"El tema busca que los jóvenes comprendan que el llamado de Jesús no termina en el perdón recibido, sino que se traduce en una misión concreta a la que se es enviado.\",\"Busca infundir la certeza de que, como a Pedro, Dios sostiene con su gracia a quien decide seguir adelante después de la caída.\"],\"evocacion\":null,\"actividadIntroductoria\":null,\"contenido\":\"Pedro recibe encomiendas concretas de Jesús: ser pescador de hombres, apacentar los corderos, pastorear las ovejas, extender la Palabra. Para Pedro la misión apenas comienza; se hace firme y avanza con la gracia de Dios mientras dirige el inicio de la Iglesia. (El documento fuente no especifica texto base ni dinámica para este tema — figura como \\\"N/A\\\" en el original.)\",\"actividadesAdicionales\":null,\"simbolos\":[],\"reflexion\":null}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"pedro\",\"codigo\":\"OZ-PEDRO\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":4,\"tema_paso\":null,\"title\":\"Pedro, el discípulo firme\",\"subtitle\":null,\"summary\":\"La fuerza no está en no caer, sino en dejarse llamar de nuevo cada vez que se cae.\",\"season_slug\":\"pascua\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"OZ-PEDRO.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"Simón Pedro, apóstol\",\"bloques\":[{\"title\":\"El camino de Simón a Pedro\",\"text\":\"Recorre el antes, el durante y el después de ser renombrado Pedro, como espejo de seguimiento para los temperamentos jóvenes y las inseguridades en la fe.\"},{\"title\":\"Para quien se siente lejos\",\"text\":\"Pensado para jóvenes que buscan profundizar su fe, especialmente quienes se sienten solos, no escuchados por Dios, o que se han alejado de Él.\"}],\"temas\":[{\"titulo\":\"Encuentro\",\"resumen\":\"A partir de la pesca milagrosa, este tema muestra que el encuentro real con Jesús no espera a que estemos exitosos o preparados, sino que llega en medio del fracaso cotidiano.\",\"puntos\":[\"La dinámica de identificar al equipo por la voz busca que los jóvenes experimenten que reconocer a Jesús va más allá de lo evidente a los sentidos.\",\"El tema busca que cada joven reconozca que sus propios fracasos no son un obstáculo para el encuentro con Cristo, sino el lugar donde Él se hace presente.\"],\"evocacion\":\"Lc 5:1-5 — Jesús enseña a las multitudes desde la barca de Simón y le pide echar las redes en la parte más profunda, después de una noche entera sin pescar nada.\",\"actividadIntroductoria\":\"Dinámica \\\"Encuentra a tu equipo\\\": en equipos de máximo 4, uno vendado debe identificar a su equipo guiándose solo por los sonidos y gritos que hacen para orientarlo.\",\"contenido\":\"Pedro era un pescador de unos 20 años con responsabilidades familiares y religiosas. Había fracasado toda la noche en su oficio, y aun así, cuando un desconocido le pide volver a intentarlo, Simón —incrédulo— obedece \\\"porque tú lo pides\\\". El encuentro con Jesús ocurre precisamente en medio del fracaso cotidiano, no fuera de él.\",\"actividadesAdicionales\":null,\"simbolos\":[\"La venda de ojos (identificar por la voz, no por la vista — como reconocer a Jesús más allá de lo evidente)\"],\"reflexion\":\"El encuentro real con Jesús no espera a que estemos exitosos o preparados: llega en medio de la noche sin pesca.\"},{\"titulo\":\"Llamado\",\"resumen\":\"Este tema muestra que Jesús conoce por completo la historia de cada joven y, aun así, lo llama y lo transforma, dándole una nueva identidad y misión.\",\"puntos\":[\"La dinámica del dibujo transmitido busca que los jóvenes noten cómo una historia se distorsiona al pasar de mano en mano, para contrastarla con la historia que Dios sí transforma para bien.\",\"El tema busca que cada joven se reconozca llamado y renombrado por Dios más allá de su pasado, con la certeza de que todo pecador tiene un futuro.\"],\"evocacion\":\"Lc 5:6-11 y Mt 16:13-19 — la pesca milagrosa hunde las barcas; Simón cae a los pies de Jesús reconociéndose pecador, y Jesús responde: \\\"No temas, desde ahora serás pescador de hombres.\\\" Más tarde, ante la confesión \\\"Tú eres el Cristo\\\", Jesús le renombra Pedro.\",\"actividadIntroductoria\":\"Dinámica \\\"Teléfono descompuesto gráfico\\\": en fila, sin voltear, se transmite un dibujo simple dibujándolo con el dedo en la espalda del compañero de enfrente, hasta llegar al primero de la fila, quien lo reproduce en papel.\",\"contenido\":\"Jesús conoce el pasado, presente y futuro de Simón y aun así lo llama y lo transforma: \\\"tú eres Pedro y sobre esta piedra edificaré mi iglesia, y las fuerzas del infierno no prevalecerán sobre ella.\\\" Todo santo tiene un pasado, y todo pecador un futuro.\",\"actividadesAdicionales\":null,\"simbolos\":[\"El dibujo que se transforma (a veces se distorsiona) al pasar de mano en mano, como la propia historia que Dios transforma\"],\"reflexion\":\"Todo santo tiene un pasado, y todo pecador un futuro.\"},{\"titulo\":\"Pasión y Muerte\",\"resumen\":\"Este tema confronta a los jóvenes con la negación y el miedo de Pedro, para mostrar que reconocer la propia fragilidad no es una derrota, sino el punto exacto donde Jesús sigue mirando con amor.\",\"puntos\":[\"La dinámica del paliacate busca que los jóvenes experimenten de forma lúdica la fragilidad y la posibilidad de la caída que todos comparten.\",\"El tema busca que cada joven identifique sus propias negaciones o cobardías sin sentir que eso cierra la puerta a la mirada amorosa de Jesús.\"],\"evocacion\":\"Mt 16:21-27 y Mc 14:27-31 — Pedro reprende a Jesús por anunciar su propia pasión (\\\"¡Quítate de delante de mí, Satanás!\\\") y más tarde promete no negarlo jamás, aunque Jesús predice sus tres negaciones.\",\"actividadIntroductoria\":\"Dinámica \\\"Vidas individuales\\\": cada joven lleva un paliacate atorado en el pantalón; el objetivo es quitarle el paliacate a los demás sin perder el propio. Quien lo pierde, queda eliminado.\",\"contenido\":\"Jesús reconoce la dureza que aún vive en el corazón de Pedro. Tras la negación, el peso de haberle fallado y el recuerdo de la mirada de Jesús queman a Pedro. El miedo invade a los discípulos y se esconden; Pedro reconoce su humanidad y su falla, pero su corazón herido duda de la resurrección anunciada.\",\"actividadesAdicionales\":null,\"simbolos\":[\"El paliacate que se pierde (la fragilidad y la caída que todos compartimos)\"],\"reflexion\":\"Reconocer la propia fragilidad —como Pedro— no es el final: es el punto exacto donde Jesús sigue mirando con amor.\"},{\"titulo\":\"Resurrección\",\"resumen\":\"A través de las tres preguntas que Jesús hace a Pedro junto al lago, este tema muestra cómo el amor de Cristo sana y restaura lo que la propia debilidad rompió.\",\"puntos\":[\"La vivencia sensorial de la Pasión busca que los jóvenes se conecten corporalmente con el sufrimiento de Cristo antes de recibir el anuncio de su resurrección.\",\"El tema busca que cada joven reciba, como Pedro, la restauración del amor de Jesús frente a sus propias caídas, sin compararse con el camino de los demás.\"],\"evocacion\":\"Jn 21:15-22 — junto al lago, Jesús pregunta tres veces a Simón Pedro \\\"¿me amas?\\\", y tres veces lo confirma en la misión de apacentar sus ovejas.\",\"actividadIntroductoria\":\"Dinámica \\\"Pasión vivencial\\\": con los ojos vendados y música de fondo, los jóvenes caminan descalzos sobre piedras, se arrodillan, reciben una corona de espinas, sienten golpes simulados de flagelación y presión en las manos como los clavos, cerrando con un momento de oración ante un crucifijo.\",\"contenido\":\"Pedro, escondido por miedo, se llena de gozo al saber a Jesús resucitado. Las tres preguntas de Jesús (\\\"¿me amas?\\\") sanan las tres negaciones. Cuando Pedro se compara con Juan, Jesús lo devuelve a lo esencial: \\\"A ti qué te importa, ¡sígueme!\\\"\",\"actividadesAdicionales\":null,\"simbolos\":[\"Corona de espinas, golpes simulados, presión en las manos (la Pasión revivida en el cuerpo)\",\"Crucifijo para la oración final\"],\"reflexion\":\"Las tres preguntas de amor deshacen las tres negaciones — el amor de Jesús restaura lo que la propia debilidad rompió.\"},{\"titulo\":\"Envío\",\"resumen\":\"Este cierre cristaliza la misión concreta que Jesús confía a Pedro —apacentar, pastorear y anunciar— como horizonte al que cada joven también es enviado tras su propio proceso de encuentro y conversión.\",\"puntos\":[\"El tema busca que los jóvenes comprendan que el llamado de Jesús no termina en el perdón recibido, sino que se traduce en una misión concreta a la que se es enviado.\",\"Busca infundir la certeza de que, como a Pedro, Dios sostiene con su gracia a quien decide seguir adelante después de la caída.\"],\"evocacion\":null,\"actividadIntroductoria\":null,\"contenido\":\"Pedro recibe encomiendas concretas de Jesús: ser pescador de hombres, apacentar los corderos, pastorear las ovejas, extender la Palabra. Para Pedro la misión apenas comienza; se hace firme y avanza con la gracia de Dios mientras dirige el inicio de la Iglesia. (El documento fuente no especifica texto base ni dinámica para este tema — figura como \\\"N/A\\\" en el original.)\",\"actividadesAdicionales\":null,\"simbolos\":[],\"reflexion\":null}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'pedro');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'juan', 'OZ-JUAN', 'oz', 'taller', 5, NULL, 'Juan, el discípulo amado', NULL, 'Quedarse hasta el final, al pie de la cruz, es la medida más honda de la amistad con Cristo.', 'pascua', '[\"cuaresma\"]', NULL, 'OZ-JUAN.jpg', 'publicado', '{\"basadoEn\":\"el apóstol Juan\",\"bloques\":[{\"title\":\"El camino del discípulo amado\",\"text\":\"Recorre el antes, el durante y el después de ser conocido como \\\"el amado\\\", como espejo de seguimiento para los temperamentos jóvenes y las inseguridades en la fe.\"},{\"title\":\"Para quien se siente lejos\",\"text\":\"Pensado para jóvenes que buscan profundizar su fe, especialmente quienes se sienten solos, no escuchados por Dios, o que se han alejado de Él.\"}],\"temas\":[{\"titulo\":\"Encuentro\",\"resumen\":\"A partir del primer encuentro de los discípulos con Jesús (\\\"Venid y veréis\\\"), este tema invita a los jóvenes a identificar su propio encuentro personal con Cristo como un momento fundacional y memorable.\",\"puntos\":[\"La dinámica de anotar y buscar coincidencias en la hora busca que los jóvenes valoren lo específico y memorable de un encuentro real, como preparación para pensar en el propio encuentro con Cristo.\",\"El tema busca que cada joven reconozca e identifique la \\\"hora\\\" concreta de su propio encuentro con Jesús, tan real como una cita en el calendario.\"],\"evocacion\":\"Jn 1:35-39 — Juan Bautista señala a Jesús como \\\"el Cordero de Dios\\\"; dos discípulos lo siguen y le preguntan dónde se hospeda. Jesús responde: \\\"Venid y veréis\\\", y se quedan con Él \\\"porque era como la hora décima.\\\"\",\"actividadIntroductoria\":\"Dinámica \\\"Coincidir\\\": cada joven escribe una hora específica; durante un minuto buscan entre ellos a quién puso la misma hora. Quienes coinciden comparten la experiencia; quienes no, comparten qué se siente no haber coincidido.\",\"contenido\":\"El encuentro con Jesucristo es fundacional: deja una huella tan profunda que, años después, no se olvida ni la hora ni el día en que sucedió. Como decía Benedicto XVI, no se comienza a ser cristiano por una decisión ética o una gran idea, sino por el encuentro con una Persona que da un nuevo horizonte a la vida.\",\"actividadesAdicionales\":null,\"simbolos\":[\"La hora exacta anotada (la fecha del propio encuentro con Cristo, memorable como la \\\"hora décima\\\" de Juan)\"],\"reflexion\":\"Recordar la hora y el día del propio encuentro con Cristo, tan real como una cita en el calendario.\"},{\"titulo\":\"Llamado\",\"resumen\":\"Este tema muestra que el llamado de Jesús no se agota en un encuentro puntual, sino que invita a una relación permanente y cercana, de verdadera amistad.\",\"puntos\":[\"La dinámica del juego busca, de forma lúdica, introducir la idea de ser \\\"hechos pescadores de hombres\\\", como les sucedió a Jacobo y Juan.\",\"El tema busca que cada joven entienda que seguir a Jesús implica dejarlo todo para quedarse con Él de forma permanente, no solo visitarlo ocasionalmente.\"],\"evocacion\":\"Lc 5:1-11 y Mt 4:21-22 — tras la pesca milagrosa, Jacobo y Juan, socios de Simón, dejan al instante la barca y a su padre Zebedeo para seguir a Jesús.\",\"actividadIntroductoria\":\"Dinámica \\\"Pescas milagrosas\\\": en parejas, se retan a piedra-papel-tijera contra otras parejas; la pareja que pierde se convierte en \\\"pescados\\\". Gana quien más parejas haya convertido.\",\"contenido\":\"No bastaba con encontrarse un día con Jesús: Él quería que Juan se quedara para siempre. Citando a Benedicto XVI: no basta con seguir y escuchar exteriormente, hay que vivir con Él y como Él, en una relación de gran familiaridad, \\\"porque a vosotros os he llamado amigos\\\" (Jn 15:13,15).\",\"actividadesAdicionales\":null,\"simbolos\":[\"El juego de convertir en \\\"pescados\\\" (ser hechos pescadores de hombres, como Jacobo y Juan)\"],\"reflexion\":\"Seguir a Jesús no es un encuentro puntual, es dejarlo todo para quedarse con Él el resto de la vida.\"},{\"titulo\":\"Pasión y muerte\",\"resumen\":\"A partir de la fidelidad de Juan, que permanece al pie de la cruz cuando otros huyen, este tema invita a los jóvenes a medir su propia amistad con Cristo por la capacidad de quedarse, no de huir.\",\"puntos\":[\"La dinámica de proteger la moneda de chocolate busca que los jóvenes experimenten, de forma física, lo que significa custodiar algo valioso que se les ha confiado.\",\"La oración al pie de la cruz busca que cada joven se comprometa a acompañar a Cristo también en los momentos difíciles, y no solo en los favorables.\"],\"evocacion\":\"Jn 13:21-27, Jn 18:15 y Jn 19:25-27 — Juan, recostado en el pecho de Jesús, pregunta por el traidor; entra con Él al patio del sumo sacerdote; y al pie de la cruz recibe a María como madre: \\\"¡He ahí tu madre!\\\"\",\"actividadIntroductoria\":\"Dinámica \\\"Te confío mi tesoro\\\": cada joven recibe una moneda de chocolate que debe conservar sin que se derrita mientras enfrenta retos físicos. Gana quien la conserve intacta.\",\"contenido\":\"La amistad de Juan con Jesús fue tan profunda que pudo saber quién lo traicionaría, entrar con Él al juicio, recibir el tesoro de resguardar a María como su propia madre, y ser testigo de la sangre y el agua que brotaron de su costado.\",\"actividadesAdicionales\":\"Oración al pie de una cruz, con María al lado, acompañada de un canto sugerido.\",\"simbolos\":[\"La moneda de chocolate que se protege de derretirse (custodiar lo que Cristo confía, como Juan custodió a María)\"],\"reflexion\":\"Juan permanece hasta el final cuando otros huyen: la fidelidad de \\\"el discípulo amado\\\" se mide en quedarse, no en huir.\"},{\"titulo\":\"Resurrección\",\"resumen\":\"Este tema presenta la fe de Juan ante el sepulcro vacío —\\\"vio y creyó\\\"— como modelo de una fe que no necesita pruebas adicionales, sino que nace del amor ya vivido con Cristo.\",\"puntos\":[\"La búsqueda de los huevos de Pascua busca que los jóvenes vivan, de forma lúdica, la experiencia de descubrir algo oculto que ya estaba ahí, como la tumba vacía.\",\"El tema busca que cada joven reconozca que su propia fe puede nacer del amor ya experimentado con Cristo, sin necesitar más pruebas o explicaciones.\"],\"evocacion\":\"Jn 20:1-9 — Juan corre al sepulcro, llega primero que Pedro, ve las envolturas de lino y \\\"vio y creyó\\\".\",\"actividadIntroductoria\":\"Dinámica \\\"Descubrir la tumba vacía\\\": búsqueda de huevos de Pascua escondidos previamente en el patio.\",\"contenido\":\"Juan fue, según la reflexión, el primero en decir en su corazón lo que luego proclamaría Christus Vivit: \\\"¡Vive Cristo, esperanza nuestra!\\\" Él está en ti, está contigo y nunca se va, incluso cuando la tristeza, los rencores o los fracasos hacen sentir viejo.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Los huevos de Pascua escondidos y hallados (la tumba vacía que se descubre, no se impone)\"],\"reflexion\":\"Ver y creer sin necesitar pruebas adicionales — la fe de Juan nace de la evidencia amorosa, no de la explicación.\"},{\"titulo\":\"Envío\",\"resumen\":\"Este cierre envía a los jóvenes, como a los discípulos tras la resurrección, a salir con el Espíritu Santo a invitar a otros al encuentro con Jesús vivo.\",\"puntos\":[\"La Adoración Eucarística busca disponer el corazón de los jóvenes para recibir el envío del Espíritu Santo antes de salir a la misión.\",\"El tema busca que cada joven se comprometa a dar testimonio activo de su amistad con Jesús, invitando a alguien más al encuentro con Él.\"],\"evocacion\":\"Jn 20:19-22, Jn 21:1-7 y Jn 21:20-24 — Jesús resucitado se presenta en medio de los discípulos, sopla sobre ellos el Espíritu Santo y los envía como el Padre lo envió a Él.\",\"actividadIntroductoria\":\"A partir de la experiencia de la tumba vacía, se guía una Adoración Eucarística: oración con ojos cerrados, exposición de Jesús Eucaristía, invocación del envío del Espíritu Santo, e invitación a salir a invitar a alguien al encuentro con Jesús.\",\"contenido\":\"Se cierra pidiendo a Jesús Resucitado que envíe su Espíritu sobre los jóvenes, y se les invita a salir del lugar de oración para invitar a alguien al encuentro con Cristo, terminando con el resguardo de Jesús Eucaristía.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Jesús Eucaristía expuesto (la presencia que envía y acompaña la misión)\"],\"reflexion\":\"Como Juan, ir y dar testimonio de la amistad con Jesús vivo.\"}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"juan\",\"codigo\":\"OZ-JUAN\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":5,\"tema_paso\":null,\"title\":\"Juan, el discípulo amado\",\"subtitle\":null,\"summary\":\"Quedarse hasta el final, al pie de la cruz, es la medida más honda de la amistad con Cristo.\",\"season_slug\":\"pascua\",\"season_secondary\":[\"cuaresma\"],\"corte_simja\":null,\"cover\":\"OZ-JUAN.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"el apóstol Juan\",\"bloques\":[{\"title\":\"El camino del discípulo amado\",\"text\":\"Recorre el antes, el durante y el después de ser conocido como \\\"el amado\\\", como espejo de seguimiento para los temperamentos jóvenes y las inseguridades en la fe.\"},{\"title\":\"Para quien se siente lejos\",\"text\":\"Pensado para jóvenes que buscan profundizar su fe, especialmente quienes se sienten solos, no escuchados por Dios, o que se han alejado de Él.\"}],\"temas\":[{\"titulo\":\"Encuentro\",\"resumen\":\"A partir del primer encuentro de los discípulos con Jesús (\\\"Venid y veréis\\\"), este tema invita a los jóvenes a identificar su propio encuentro personal con Cristo como un momento fundacional y memorable.\",\"puntos\":[\"La dinámica de anotar y buscar coincidencias en la hora busca que los jóvenes valoren lo específico y memorable de un encuentro real, como preparación para pensar en el propio encuentro con Cristo.\",\"El tema busca que cada joven reconozca e identifique la \\\"hora\\\" concreta de su propio encuentro con Jesús, tan real como una cita en el calendario.\"],\"evocacion\":\"Jn 1:35-39 — Juan Bautista señala a Jesús como \\\"el Cordero de Dios\\\"; dos discípulos lo siguen y le preguntan dónde se hospeda. Jesús responde: \\\"Venid y veréis\\\", y se quedan con Él \\\"porque era como la hora décima.\\\"\",\"actividadIntroductoria\":\"Dinámica \\\"Coincidir\\\": cada joven escribe una hora específica; durante un minuto buscan entre ellos a quién puso la misma hora. Quienes coinciden comparten la experiencia; quienes no, comparten qué se siente no haber coincidido.\",\"contenido\":\"El encuentro con Jesucristo es fundacional: deja una huella tan profunda que, años después, no se olvida ni la hora ni el día en que sucedió. Como decía Benedicto XVI, no se comienza a ser cristiano por una decisión ética o una gran idea, sino por el encuentro con una Persona que da un nuevo horizonte a la vida.\",\"actividadesAdicionales\":null,\"simbolos\":[\"La hora exacta anotada (la fecha del propio encuentro con Cristo, memorable como la \\\"hora décima\\\" de Juan)\"],\"reflexion\":\"Recordar la hora y el día del propio encuentro con Cristo, tan real como una cita en el calendario.\"},{\"titulo\":\"Llamado\",\"resumen\":\"Este tema muestra que el llamado de Jesús no se agota en un encuentro puntual, sino que invita a una relación permanente y cercana, de verdadera amistad.\",\"puntos\":[\"La dinámica del juego busca, de forma lúdica, introducir la idea de ser \\\"hechos pescadores de hombres\\\", como les sucedió a Jacobo y Juan.\",\"El tema busca que cada joven entienda que seguir a Jesús implica dejarlo todo para quedarse con Él de forma permanente, no solo visitarlo ocasionalmente.\"],\"evocacion\":\"Lc 5:1-11 y Mt 4:21-22 — tras la pesca milagrosa, Jacobo y Juan, socios de Simón, dejan al instante la barca y a su padre Zebedeo para seguir a Jesús.\",\"actividadIntroductoria\":\"Dinámica \\\"Pescas milagrosas\\\": en parejas, se retan a piedra-papel-tijera contra otras parejas; la pareja que pierde se convierte en \\\"pescados\\\". Gana quien más parejas haya convertido.\",\"contenido\":\"No bastaba con encontrarse un día con Jesús: Él quería que Juan se quedara para siempre. Citando a Benedicto XVI: no basta con seguir y escuchar exteriormente, hay que vivir con Él y como Él, en una relación de gran familiaridad, \\\"porque a vosotros os he llamado amigos\\\" (Jn 15:13,15).\",\"actividadesAdicionales\":null,\"simbolos\":[\"El juego de convertir en \\\"pescados\\\" (ser hechos pescadores de hombres, como Jacobo y Juan)\"],\"reflexion\":\"Seguir a Jesús no es un encuentro puntual, es dejarlo todo para quedarse con Él el resto de la vida.\"},{\"titulo\":\"Pasión y muerte\",\"resumen\":\"A partir de la fidelidad de Juan, que permanece al pie de la cruz cuando otros huyen, este tema invita a los jóvenes a medir su propia amistad con Cristo por la capacidad de quedarse, no de huir.\",\"puntos\":[\"La dinámica de proteger la moneda de chocolate busca que los jóvenes experimenten, de forma física, lo que significa custodiar algo valioso que se les ha confiado.\",\"La oración al pie de la cruz busca que cada joven se comprometa a acompañar a Cristo también en los momentos difíciles, y no solo en los favorables.\"],\"evocacion\":\"Jn 13:21-27, Jn 18:15 y Jn 19:25-27 — Juan, recostado en el pecho de Jesús, pregunta por el traidor; entra con Él al patio del sumo sacerdote; y al pie de la cruz recibe a María como madre: \\\"¡He ahí tu madre!\\\"\",\"actividadIntroductoria\":\"Dinámica \\\"Te confío mi tesoro\\\": cada joven recibe una moneda de chocolate que debe conservar sin que se derrita mientras enfrenta retos físicos. Gana quien la conserve intacta.\",\"contenido\":\"La amistad de Juan con Jesús fue tan profunda que pudo saber quién lo traicionaría, entrar con Él al juicio, recibir el tesoro de resguardar a María como su propia madre, y ser testigo de la sangre y el agua que brotaron de su costado.\",\"actividadesAdicionales\":\"Oración al pie de una cruz, con María al lado, acompañada de un canto sugerido.\",\"simbolos\":[\"La moneda de chocolate que se protege de derretirse (custodiar lo que Cristo confía, como Juan custodió a María)\"],\"reflexion\":\"Juan permanece hasta el final cuando otros huyen: la fidelidad de \\\"el discípulo amado\\\" se mide en quedarse, no en huir.\"},{\"titulo\":\"Resurrección\",\"resumen\":\"Este tema presenta la fe de Juan ante el sepulcro vacío —\\\"vio y creyó\\\"— como modelo de una fe que no necesita pruebas adicionales, sino que nace del amor ya vivido con Cristo.\",\"puntos\":[\"La búsqueda de los huevos de Pascua busca que los jóvenes vivan, de forma lúdica, la experiencia de descubrir algo oculto que ya estaba ahí, como la tumba vacía.\",\"El tema busca que cada joven reconozca que su propia fe puede nacer del amor ya experimentado con Cristo, sin necesitar más pruebas o explicaciones.\"],\"evocacion\":\"Jn 20:1-9 — Juan corre al sepulcro, llega primero que Pedro, ve las envolturas de lino y \\\"vio y creyó\\\".\",\"actividadIntroductoria\":\"Dinámica \\\"Descubrir la tumba vacía\\\": búsqueda de huevos de Pascua escondidos previamente en el patio.\",\"contenido\":\"Juan fue, según la reflexión, el primero en decir en su corazón lo que luego proclamaría Christus Vivit: \\\"¡Vive Cristo, esperanza nuestra!\\\" Él está en ti, está contigo y nunca se va, incluso cuando la tristeza, los rencores o los fracasos hacen sentir viejo.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Los huevos de Pascua escondidos y hallados (la tumba vacía que se descubre, no se impone)\"],\"reflexion\":\"Ver y creer sin necesitar pruebas adicionales — la fe de Juan nace de la evidencia amorosa, no de la explicación.\"},{\"titulo\":\"Envío\",\"resumen\":\"Este cierre envía a los jóvenes, como a los discípulos tras la resurrección, a salir con el Espíritu Santo a invitar a otros al encuentro con Jesús vivo.\",\"puntos\":[\"La Adoración Eucarística busca disponer el corazón de los jóvenes para recibir el envío del Espíritu Santo antes de salir a la misión.\",\"El tema busca que cada joven se comprometa a dar testimonio activo de su amistad con Jesús, invitando a alguien más al encuentro con Él.\"],\"evocacion\":\"Jn 20:19-22, Jn 21:1-7 y Jn 21:20-24 — Jesús resucitado se presenta en medio de los discípulos, sopla sobre ellos el Espíritu Santo y los envía como el Padre lo envió a Él.\",\"actividadIntroductoria\":\"A partir de la experiencia de la tumba vacía, se guía una Adoración Eucarística: oración con ojos cerrados, exposición de Jesús Eucaristía, invocación del envío del Espíritu Santo, e invitación a salir a invitar a alguien al encuentro con Jesús.\",\"contenido\":\"Se cierra pidiendo a Jesús Resucitado que envíe su Espíritu sobre los jóvenes, y se les invita a salir del lugar de oración para invitar a alguien al encuentro con Cristo, terminando con el resguardo de Jesús Eucaristía.\",\"actividadesAdicionales\":null,\"simbolos\":[\"Jesús Eucaristía expuesto (la presencia que envía y acompaña la misión)\"],\"reflexion\":\"Como Juan, ir y dar testimonio de la amistad con Jesús vivo.\"}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'juan');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'zaqueo', 'OZ-ZAQUEO', 'oz', 'taller', 1, NULL, 'Zaqueo', NULL, 'No hace falta que te vean para que Cristo te llame por tu nombre.', 'ordinario', NULL, NULL, 'OZ-ZAQUEO.jpg', 'proximamente', '{\"basadoEn\":\"Zaqueo, el publicano de Jericó\",\"bloques\":[{\"title\":\"Subirse al árbol sin ser visto\",\"text\":\"Zaqueo era bajito, rechazado por todos y curioso: se subió a un árbol solo para ver pasar a Jesús, sin esperar nada a cambio. El primer paso hacia Cristo no exige compromiso, solo un poco de curiosidad.\"},{\"title\":\"Llamado por nombre, frente a todos\",\"text\":\"Jesús no espera que baje solo ni en secreto: lo llama en voz alta, delante de la misma gente que lo señalaba como traidor. Ser visto por Dios en público desarma la vergüenza del propio pasado.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"zaqueo\",\"codigo\":\"OZ-ZAQUEO\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":1,\"tema_paso\":null,\"title\":\"Zaqueo\",\"subtitle\":null,\"summary\":\"No hace falta que te vean para que Cristo te llame por tu nombre.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-ZAQUEO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Zaqueo, el publicano de Jericó\",\"bloques\":[{\"title\":\"Subirse al árbol sin ser visto\",\"text\":\"Zaqueo era bajito, rechazado por todos y curioso: se subió a un árbol solo para ver pasar a Jesús, sin esperar nada a cambio. El primer paso hacia Cristo no exige compromiso, solo un poco de curiosidad.\"},{\"title\":\"Llamado por nombre, frente a todos\",\"text\":\"Jesús no espera que baje solo ni en secreto: lo llama en voz alta, delante de la misma gente que lo señalaba como traidor. Ser visto por Dios en público desarma la vergüenza del propio pasado.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'zaqueo');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'bartimeo', 'OZ-BARTIMEO', 'oz', 'taller', 2, NULL, 'Bartimeo', NULL, 'El grito que no se calla, aunque la multitud mande callar.', 'ordinario', NULL, NULL, 'OZ-BARTIMEO.jpg', 'proximamente', '{\"basadoEn\":\"Bartimeo, el ciego de Jericó\",\"bloques\":[{\"title\":\"\\\"¡Cállate!\\\" — y él gritó más fuerte\",\"text\":\"Bartimeo grita pidiendo compasión y la multitud lo manda callar. Aun así insiste. La fe a veces exige gritar la propia necesidad pese al \\\"qué dirán\\\" del grupo, la familia o las redes.\"},{\"title\":\"\\\"¿Qué quieres que haga por ti?\\\"\",\"text\":\"Jesús se detiene y pregunta lo obvio, porque quiere que Bartimeo lo diga con sus propias palabras. Es la misma pregunta que puede hacerse hoy, de frente, en una oración de petición personal.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"bartimeo\",\"codigo\":\"OZ-BARTIMEO\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":2,\"tema_paso\":null,\"title\":\"Bartimeo\",\"subtitle\":null,\"summary\":\"El grito que no se calla, aunque la multitud mande callar.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-BARTIMEO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"Bartimeo, el ciego de Jericó\",\"bloques\":[{\"title\":\"\\\"¡Cállate!\\\" — y él gritó más fuerte\",\"text\":\"Bartimeo grita pidiendo compasión y la multitud lo manda callar. Aun así insiste. La fe a veces exige gritar la propia necesidad pese al \\\"qué dirán\\\" del grupo, la familia o las redes.\"},{\"title\":\"\\\"¿Qué quieres que haga por ti?\\\"\",\"text\":\"Jesús se detiene y pregunta lo obvio, porque quiere que Bartimeo lo diga con sus propias palabras. Es la misma pregunta que puede hacerse hoy, de frente, en una oración de petición personal.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'bartimeo');
