  SELECT 'camino-damasco', 'OZ-CAMINODAMASCO', 'oz', 'retiro', 3, NULL, 'Camino a Damasco', NULL, 'La conversión más radical de la Biblia, para quien viene de frente en contra.', 'ordinario', NULL, NULL, 'OZ-CAMINODAMASCO.jpg', 'proximamente', '{\"basadoEn\":\"la conversión de Saulo camino a Damasco\",\"bloques\":[{\"title\":\"Perseguir de frente, no por indiferencia\",\"text\":\"Saulo no era un indiferente: iba armado contra los cristianos. A veces el camino de vuelta empieza no en la tibieza, sino en el rechazo abierto y el pasado del que se avergüenza.\"},{\"title\":\"Tres días de ceguera\",\"text\":\"Cae, queda ciego y depende por completo de otros para llegar a la ciudad. Antes de ver de nuevo, tiene que aceptar no ver nada.\"},{\"title\":\"Una venda que alguien más retira\",\"text\":\"Ananías, con miedo, le impone las manos y la ceguera cae \\\"como escamas\\\". Nadie se convierte del todo solo: hace falta alguien dispuesto a acercarse al que antes daba miedo.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"camino-damasco\",\"codigo\":\"OZ-CAMINODAMASCO\",\"derej_slug\":\"oz\",\"tipo\":\"retiro\",\"paso\":3,\"tema_paso\":null,\"title\":\"Camino a Damasco\",\"subtitle\":null,\"summary\":\"La conversión más radical de la Biblia, para quien viene de frente en contra.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-CAMINODAMASCO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la conversión de Saulo camino a Damasco\",\"bloques\":[{\"title\":\"Perseguir de frente, no por indiferencia\",\"text\":\"Saulo no era un indiferente: iba armado contra los cristianos. A veces el camino de vuelta empieza no en la tibieza, sino en el rechazo abierto y el pasado del que se avergüenza.\"},{\"title\":\"Tres días de ceguera\",\"text\":\"Cae, queda ciego y depende por completo de otros para llegar a la ciudad. Antes de ver de nuevo, tiene que aceptar no ver nada.\"},{\"title\":\"Una venda que alguien más retira\",\"text\":\"Ananías, con miedo, le impone las manos y la ceguera cae \\\"como escamas\\\". Nadie se convierte del todo solo: hace falta alguien dispuesto a acercarse al que antes daba miedo.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"2 a 3 días\",\"desc\":\"Formato de fin de semana o campamento: viernes/sábado por la tarde a domingo, con jornadas completas de dinámicas, oración y descanso entre cada momento.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"25 a 80 personas\",\"desc\":\"Garantiza el trabajo en grupos pequeños (escuadrones o mesas) y un clima de confianza para la confesión y el testimonio personal.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'camino-damasco');
