  SELECT 'joven-rico', 'OZ-JOVENRICO', 'oz', 'taller', 6, NULL, 'El joven rico', NULL, 'Cumplir todo y aun así irse triste porque hay una cosa que no se suelta.', 'ordinario', NULL, NULL, 'OZ-JOVENRICO.jpg', 'proximamente', '{\"basadoEn\":\"el joven rico que se acercó a Jesús\",\"bloques\":[{\"title\":\"Cumplir todo, correctamente\",\"text\":\"El joven guarda los mandamientos desde su juventud: va a misa, es buena onda, hace lo que se espera de él. Y aun así algo le falta.\"},{\"title\":\"\\\"Lo miró y lo amó\\\" — antes de pedirle nada\",\"text\":\"Jesús no lo regaña por lo que le falta; primero lo mira con amor. Solo después le pide soltar lo que no puede soltar: un celular, una imagen, una relación, un ídolo silencioso.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"joven-rico\",\"codigo\":\"OZ-JOVENRICO\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":6,\"tema_paso\":null,\"title\":\"El joven rico\",\"subtitle\":null,\"summary\":\"Cumplir todo y aun así irse triste porque hay una cosa que no se suelta.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-JOVENRICO.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el joven rico que se acercó a Jesús\",\"bloques\":[{\"title\":\"Cumplir todo, correctamente\",\"text\":\"El joven guarda los mandamientos desde su juventud: va a misa, es buena onda, hace lo que se espera de él. Y aun así algo le falta.\"},{\"title\":\"\\\"Lo miró y lo amó\\\" — antes de pedirle nada\",\"text\":\"Jesús no lo regaña por lo que le falta; primero lo mira con amor. Solo después le pide soltar lo que no puede soltar: un celular, una imagen, una relación, un ídolo silencioso.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'joven-rico');
