  SELECT 'tomas', 'OZ-TOMAS', 'oz', 'taller', 7, NULL, 'Tomás', NULL, 'La duda no se castiga: se invita a tocar la herida.', 'ordinario', NULL, NULL, 'OZ-TOMAS.jpg', 'proximamente', '{\"basadoEn\":\"el apóstol Tomás\",\"bloques\":[{\"title\":\"Dudar no es traicionar\",\"text\":\"Tomás no cree en el relato de los demás apóstoles y lo dice sin rodeos. Hoy dudar de la fe es la norma entre los jóvenes, no la excepción — y no por eso se deja de ser discípulo.\"},{\"title\":\"Pon tu dedo aquí\",\"text\":\"Jesús no lo excluye por dudar: vuelve solo para él y le ofrece tocar la herida. La duda honesta, dicha en voz alta, puede ser el lugar exacto donde Cristo se hace presente.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"tomas\",\"codigo\":\"OZ-TOMAS\",\"derej_slug\":\"oz\",\"tipo\":\"taller\",\"paso\":7,\"tema_paso\":null,\"title\":\"Tomás\",\"subtitle\":null,\"summary\":\"La duda no se castiga: se invita a tocar la herida.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-TOMAS.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"el apóstol Tomás\",\"bloques\":[{\"title\":\"Dudar no es traicionar\",\"text\":\"Tomás no cree en el relato de los demás apóstoles y lo dice sin rodeos. Hoy dudar de la fe es la norma entre los jóvenes, no la excepción — y no por eso se deja de ser discípulo.\"},{\"title\":\"Pon tu dedo aquí\",\"text\":\"Jesús no lo excluye por dudar: vuelve solo para él y le ofrece tocar la herida. La duda honesta, dicha en voz alta, puede ser el lugar exacto donde Cristo se hace presente.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"4 a 6 horas\",\"desc\":\"Sesión intensiva de una sola jornada (mañana o tarde), con tiempo suficiente para la enseñanza, la dinámica vivencial y el cierre de oración.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"15 a 40 personas\",\"desc\":\"Permite el acompañamiento cercano de los facilitadores durante las dinámicas y el trabajo en subgrupos.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'tomas');
