  SELECT 'getsemani', 'OZ-GETSEMANI', 'oz', 'hora_santa', 9, NULL, 'Getsemaní', NULL, 'Acompañar el sufrimiento de Cristo, no solo recibir de Él.', 'cuaresma', NULL, NULL, 'OZ-GETSEMANI.jpg', 'proximamente', '{\"basadoEn\":\"la agonía de Jesús en el huerto de Getsemaní\",\"bloques\":[{\"title\":\"\\\"Quédense aquí y velen conmigo\\\"\",\"text\":\"Jesús pide compañía en su hora más oscura, no soluciones. Acompañar a alguien que sufre —empezando por Cristo mismo— a veces es solo eso: quedarse despierto.\"},{\"title\":\"Se durmieron\",\"text\":\"Los discípulos, agotados, se quedan dormidos justo cuando más se les necesita. Es el retrato honesto de la pereza espiritual: querer acompañar y, aun así, fallar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"getsemani\",\"codigo\":\"OZ-GETSEMANI\",\"derej_slug\":\"oz\",\"tipo\":\"hora_santa\",\"paso\":9,\"tema_paso\":null,\"title\":\"Getsemaní\",\"subtitle\":null,\"summary\":\"Acompañar el sufrimiento de Cristo, no solo recibir de Él.\",\"season_slug\":\"cuaresma\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-GETSEMANI.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la agonía de Jesús en el huerto de Getsemaní\",\"bloques\":[{\"title\":\"\\\"Quédense aquí y velen conmigo\\\"\",\"text\":\"Jesús pide compañía en su hora más oscura, no soluciones. Acompañar a alguien que sufre —empezando por Cristo mismo— a veces es solo eso: quedarse despierto.\"},{\"title\":\"Se durmieron\",\"text\":\"Los discípulos, agotados, se quedan dormidos justo cuando más se les necesita. Es el retrato honesto de la pereza espiritual: querer acompañar y, aun así, fallar.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'getsemani');
