  SELECT 'pentecostes', 'OZ-PENTECOSTES', 'oz', 'hora_santa', 10, NULL, 'Pentecostés', NULL, 'El fuego que se recibe no se guarda: se manda a compartir.', 'pentecostes', NULL, NULL, 'OZ-PENTECOSTES.jpg', 'proximamente', '{\"basadoEn\":\"la venida del Espíritu Santo sobre los apóstoles en el Cenáculo\",\"bloques\":[{\"title\":\"Un viento que llena toda la casa\",\"text\":\"Los apóstoles esperaban encerrados, con miedo, hasta que el Espíritu llega como viento y fuego y los saca de ese cuarto para siempre. Cierra el recorrido de Oz: todo lo recibido en el camino apunta hacia afuera.\"},{\"title\":\"De vela en vela\",\"text\":\"El fuego de Pentecostés no se queda en un apóstol: se reparte. Un rito de fuego real, pasado de mano en mano, puede sellar el cierre de un campamento, una confirmación o el inicio del año pastoral.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"pentecostes\",\"codigo\":\"OZ-PENTECOSTES\",\"derej_slug\":\"oz\",\"tipo\":\"hora_santa\",\"paso\":10,\"tema_paso\":null,\"title\":\"Pentecostés\",\"subtitle\":null,\"summary\":\"El fuego que se recibe no se guarda: se manda a compartir.\",\"season_slug\":\"pentecostes\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"OZ-PENTECOSTES.jpg\",\"estado_catalogo\":\"proximamente\",\"body\":{\"basadoEn\":\"la venida del Espíritu Santo sobre los apóstoles en el Cenáculo\",\"bloques\":[{\"title\":\"Un viento que llena toda la casa\",\"text\":\"Los apóstoles esperaban encerrados, con miedo, hasta que el Espíritu llega como viento y fuego y los saca de ese cuarto para siempre. Cierra el recorrido de Oz: todo lo recibido en el camino apunta hacia afuera.\"},{\"title\":\"De vela en vela\",\"text\":\"El fuego de Pentecostés no se queda en un apóstol: se reparte. Un rito de fuego real, pasado de mano en mano, puede sellar el cierre de un campamento, una confirmación o el inicio del año pastoral.\"}],\"temas\":[],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}}' FROM DUAL
  WHERE NOT EXISTS (SELECT 1 FROM retreats WHERE slug = 'pentecostes');
INSERT INTO retreats (`slug`, `codigo`, `derej_slug`, `tipo`, `paso`, `tema_paso`, `title`, `subtitle`, `summary`, `season_slug`, `season_secondary`, `corte_simja`, `cover`, `estado_catalogo`, `body`, status, live_from, published_snapshot)
  SELECT 'jesucristo-nuestra-esperanza', 'JAIM-JESUCRISTONUESTRAESPERANZA', 'jaim', 'hora_santa', NULL, NULL, 'Jesucristo Nuestra Esperanza', NULL, 'Jesús es la Puerta que nunca se cierra, el Camino que guía y la Esperanza que no defrauda.', 'ordinario', NULL, NULL, 'JAIM-JESUCRISTONUESTRAESPERANZA.jpg', 'publicado', '{\"basadoEn\":\"Jesús como Puerta, Camino y Esperanza (Jn 10, Col 1, Heb 6 y 10)\",\"bloques\":[{\"title\":\"Descanso, fortaleza y dirección\",\"text\":\"Una Adoración Eucarística para reconocer a Jesús como nuestra única esperanza, renovando la confianza en su promesa de salvación.\"},{\"title\":\"Para toda la congregación\",\"text\":\"Dirigida a la congregación sin distinción de edad ni género, celebrada particularmente a fin de año para enfatizar el mensaje de la esperanza.\"}],\"temas\":[{\"titulo\":\"Frente a la puerta\",\"resumen\":\"A partir de la imagen de la puerta que nadie puede cerrar (Ap 3:7-8), este tema invita a la congregación a reconocer en Jesús una entrada que siempre permanece abierta, incluso cuando la vida ha cerrado otras puertas.\",\"puntos\":[\"El canto y la oración inicial buscan disponer el corazón de los presentes para adorar y acoger la presencia de Jesús como puerta abierta.\",\"El momento de oración personal ante la estructura de la puerta busca que cada persona confronte las puertas que la vida le ha cerrado, y las entregue confiando en la puerta que Jesús ofrece.\"],\"evocacion\":\"Ap 3:7-8 — \\\"Te he puesto delante una puerta abierta que nadie puede cerrar.\\\"\",\"actividadIntroductoria\":\"Canto inicial \\\"El Rey de la Gloria\\\" (Hakuna Group Music) y oración inicial de entrada, seguida del canto de alabanza.\",\"contenido\":\"Jesús es la puerta que espera, abierta, sin que nadie pueda cerrarla — incluso para quien aún no lo conoce (Jn 10:7-9). Contrasta con las puertas que la vida cierra en la cara: esta nunca se cierra.\",\"actividadesAdicionales\":\"Canto de acompañamiento \\\"Entra\\\" (MNM RCCES) durante la oración personal ante la puerta.\",\"simbolos\":[\"Estructura que simula unas puertas abiertas, con la frase \\\"Yo soy la Esperanza\\\" en la parte alta\"],\"reflexion\":\"¿Cuántas veces nos han cerrado puertas? Esta puerta, en cambio, siempre ofrece la entrada.\"},{\"titulo\":\"Jesús es también el camino\",\"resumen\":\"Este tema presenta a Jesús no solo como destino sino como guía activo del camino, invitando a confiar en cada paso que Él va marcando.\",\"puntos\":[\"La escritura en el post-it busca que cada persona nombre concretamente una necesidad o deseo propio antes de presentarlo ante Jesús.\",\"El tema busca llevar a la congregación a descansar y confiar en los pasos que Jesús va marcando, en lugar de exigir ver el camino completo de antemano.\"],\"evocacion\":\"Heb 10:19-20 — el camino nuevo y vivo inaugurado por la sangre de Jesús.\",\"actividadIntroductoria\":null,\"contenido\":\"Confiar en Jesús como camino implica no solo caminar hacia Él, sino también descansar y confiar en los pasos que Él va marcando (Is 30:21). Es guía, no solo destino.\",\"actividadesAdicionales\":\"Exhortación: se invita a la congregación a pensar en algo que necesitaron o desearon alguna vez, y a escribirlo en un post-it.\",\"simbolos\":[\"Post-its con lo que cada persona necesita o desea\"],\"reflexion\":null},{\"titulo\":\"¿Dónde está la Esperanza?\",\"resumen\":\"Este tema confronta a la congregación con la insuficiencia de las propias fuerzas, para reconocer que la esperanza verdadera solo se sostiene en Cristo.\",\"puntos\":[\"La invitación a caminar físicamente hacia la puerta busca que cada persona exprese, con su cuerpo, el acto de acercarse a la esperanza que solo Cristo ofrece.\",\"El tema busca que la congregación reconozca sus propios límites y descubra que en Él se encuentra todo lo necesario para alcanzar la plenitud.\"],\"evocacion\":\"Col 1:27 — \\\"Cristo para ustedes, esperanza de gloria.\\\"\",\"actividadIntroductoria\":null,\"contenido\":\"La verdadera esperanza está en el camino y en la puerta: por nuestras propias fuerzas no podemos, siempre necesitamos las suyas (Rom 5:5,11). Él se convierte en todo lo que necesitamos para llegar a su plenitud.\",\"actividadesAdicionales\":\"Exhortación a caminar hacia la puerta para contemplar la esperanza. Alabanza de acompañamiento \\\"Quiero conocer a Jesús\\\" (Generación 12).\",\"simbolos\":[],\"reflexion\":null},{\"titulo\":\"He aquí nuestra esperanza\",\"resumen\":\"Retomando la imagen del ancla firme y segura (Heb 6:18-20), este tema afirma que, a los pies de la puerta de salvación y en el camino de la verdad, ya no hay nada que temer.\",\"puntos\":[\"El momento de alabanza busca sostener en la congregación un clima de confianza y adoración mientras se profundiza en la certeza de la esperanza cristiana.\",\"El tema busca afianzar en cada persona la convicción de que, en Cristo, todo temor y toda imposibilidad quedan resueltos.\"],\"evocacion\":\"Heb 6:18-20 — el ancla firme y segura que penetra más allá de la cortina del Templo, donde Jesús entró como precursor y sumo sacerdote perpetuo.\",\"actividadIntroductoria\":null,\"contenido\":\"A los pies de la puerta de salvación y en el camino de la verdad ya no hay nada que temer ni nada imposible: todo es encontrado y resuelto en Él.\",\"actividadesAdicionales\":\"Alabanza de acompañamiento \\\"El rostro de mi amado\\\" (Monte Santo y Belén Losa).\",\"simbolos\":[],\"reflexion\":null},{\"titulo\":\"Contemplación\",\"resumen\":\"Este cierre invita a contemplar a Jesucristo mismo como la esperanza viva que se hace presente en toda necesidad, persecución o tormenta, devolviendo siempre al camino a quien se desvía.\",\"puntos\":[\"Completar el post-it con la frase \\\"Con Jesucristo\\\" busca que cada persona una explícitamente su necesidad o deseo personal a la certeza de la presencia de Cristo.\",\"El cierre busca dejar en la congregación la seguridad de que, aunque se desvíen del camino, el amor de Jesús siempre los trae de vuelta.\"],\"evocacion\":null,\"actividadIntroductoria\":null,\"contenido\":\"Jesucristo mismo es la esperanza que vive y está frente a nosotros — el aliento necesario para seguir, que se entrega para satisfacer la necesidad, la persecución y la tormenta, haciéndose calma, paz, firmeza y plenitud.\",\"actividadesAdicionales\":\"Exhortación: en el mismo post-it, se pide añadir \\\"Con Jesucristo\\\" a lo ya escrito. Alabanza de acompañamiento \\\"Yahweh se manifestará\\\" (Oasis).\",\"simbolos\":[\"El post-it completado con lo escrito más \\\"Con Jesucristo\\\"\"],\"reflexion\":\"Aunque nos desviemos, Él con amor nos vuelve a traer de vuelta.\"}],\"cronograma\":[],\"fichaTecnica\":[{\"icon\":\"clock\",\"label\":\"Duración Sugerida\",\"value\":\"1 a 3 horas\",\"desc\":\"Adoración eucarística con tiempo de silencio, prédica breve, cantos y oración comunitaria ante el Santísimo.\"},{\"icon\":\"people\",\"label\":\"Capacidad Recomendada\",\"value\":\"30 a 120 personas\",\"desc\":\"Formato de asamblea abierta; se ajusta al aforo real de la capilla o templo donde se celebre.\"},{\"icon\":\"building\",\"label\":\"Requisitos de Espacio\",\"value\":\"Salón & Templo / Capilla\",\"desc\":\"Capilla con Sagrario habilitado para vigilia nocturna y salón de usos múltiples con sillas móviles para las dinámicas.\"}],\"chips\":null,\"chipsLabel\":null}', 'publicado', UTC_TIMESTAMP(), '{\"slug\":\"jesucristo-nuestra-esperanza\",\"codigo\":\"JAIM-JESUCRISTONUESTRAESPERANZA\",\"derej_slug\":\"jaim\",\"tipo\":\"hora_santa\",\"paso\":null,\"tema_paso\":null,\"title\":\"Jesucristo Nuestra Esperanza\",\"subtitle\":null,\"summary\":\"Jesús es la Puerta que nunca se cierra, el Camino que guía y la Esperanza que no defrauda.\",\"season_slug\":\"ordinario\",\"season_secondary\":null,\"corte_simja\":null,\"cover\":\"JAIM-JESUCRISTONUESTRAESPERANZA.jpg\",\"estado_catalogo\":\"publicado\",\"body\":{\"basadoEn\":\"Jesús como Puerta, Camino y Esperanza (Jn 10, Col 1, Heb 6 y 10)\",\"bloques\":[{\"title\":