  SELECT 'Josué 1:9', 'Sé fuerte y valiente. No tengas miedo ni te acobardes, porque el Señor tu Dios estará contigo dondequiera que vayas.', 'RSV-2CE', 'publicado', UTC_TIMESTAMP(), '{\"ref\":\"Josué 1:9\",\"text_es\":\"Sé fuerte y valiente. No tengas miedo ni te acobardes, porque el Señor tu Dios estará contigo dondequiera que vayas.\",\"version_en\":\"RSV-2CE\"}' FROM DUAL
